	cmd := acmd.Runner{
		Commands: acmd.Commands{
			"check":   acmd.Command{Name: "check", Description: "run linter over specified targets", Exec: ...},
			...
		},
	}
	cmd.Usage = func() { ... }
	return cmd.Run(args)
}
```

