package main

import (
	"encoding/json"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"log"
	"os"
	"os/exec"
	"strings"
	"time"
)

type Pkg struct {
	ImportPath string
	Export     string
	Name       string
	Dir        string
	GoFiles    []string
	ImportMap  map[string]string
	Imports    []string
}

func main() {
	targets := []string{"net/http", "encoding/json", "go/ast", "go/parser", "go/token", "go/types"}
	start := time.Now()
	out, err := exec.Command("go", append([]string{"list", "-export", "-json", "-deps"}, targets...)...).Output()
	if err != nil {
		log.Fatal(err, string(out))
	}
	fmt.Println("go list:", time.Since(start))
	dec := json.NewDecoder(strings.NewReader(string(out)))
	exports := map[string]string{}
	names := map[string]string{}
	for {
		var p Pkg
		if err := dec.Decode(&p); err != nil {
			break
		}
		exports[p.ImportPath] = p.Export
		names[p.ImportPath] = p.Name
	}
	fset := token.NewFileSet()
	imp := importer.ForCompiler(fset, "gc", func(path string) (io.ReadCloser, error) {
		f, ok := exports[path]
		if !ok || f == "" {
			return nil, fmt.Errorf("no export for %s", path)
		}
		return os.Open(f)
	})
	t0 := time.Now()
	cfg := types.Config{Importer: imp}
	af, err := parser.ParseFile(fset, "main.go", src, parser.ParseComments)
	if err != nil {
		log.Fatal(err)
	}
	info := &types.Info{Types: map[ast.Expr]types.TypeAndValue{}, Defs: map[*ast.Ident]types.Object{}, Uses: map[*ast.Ident]types.Object{}, Selections: map[*ast.SelectorExpr]*types.Selection{}, Scopes: map[ast.Node]types.Scope{}, Implicits: map[ast.Node]types.Object{}}
	p, err := cfg.Check("main", fset, []*ast.File{af}, info)
	fmt.Println("check:", time.Since(t0), "err:", err, "pkg:", p)
	fmt.Println("types:", len(info.Types), "defs:", len(info.Defs), "sels:", len(info.Selections))
}

const src = `package main

import (
	"fmt"
	"net/http"
)

func main() {
	req, _ := http.NewRequest("GET", "http://x", nil)
	fmt.Println(req.Method, req.URL.String())
}
`
EOF
go build -o ./imp2 ./... 2>&1|head -5 && time ./imp2"}

