		stderr("%v", err)
	}
}

func run(args []string) error {
	if len(args) == 0 {
		stderr("no args provided")
		return nil
	}
	switch args[0] {
	case "help":
		printUsage()
		return nil
	case "version":
		fmt.Printf("go-critic version: %s\n\n", version)
		return nil
	case "check":
		prog := newProgram()
		return prog.runCheck(args[1:])
	case "doc":
		prog := newProgram()
		return prog.runDoc(args[1:])
	default:
		fmt.Printf("%q unknown command\nRun \"go-critic help\" for usage.\n\n", args[0])
		return fmt.Errorf("no such command %q", args[0])
	}
}

func printUsage() {
	fmt.Printf(`Usage:

    go-critic <command> [arguments...]

The commands are:

    check             run linter over specified targets
    doc               get installed checkers documentation
    help              shows help message
    version           shows version of the application

Version: %s

`, version)
}

func stderr(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
}

func debug(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "\tdebug: "+format+"\n", args...)
}
EOF
gofmt -w main.go && echo ok"}

