{"command": "cat > loader.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// listPackage is a subset of the `go list -json` package structure.
type listPackage struct {
	Dir             string
	ImportPath      string
	Name            string
	Export          string
	GoFiles         []string
	CompiledGoFiles []string
	IgnoredGoFiles  []string
	ImportMap       map[string]string
	Imports         []string
	ForTest         string
	Standard        bool
	DepOnly         bool
	Error           *listPkgError
}

type listPkgError struct {
	Err string
	Pos string
}

// Package is a loaded Go package with the syntax trees and the type information.
type Package struct {
	ID      string
	PkgPath string
	Name    string
	Dir     string

	FSet   *token.FileSet
	Syntax []*ast.File

	Types *types.Package
	Info  *types.Info

	// IllType is true if the package type information is incomplete.
	IllType bool

	// typesInfo reports whether the type info map was populated.
	typesInfo bool

	// goFiles is a list of the package source file names, relative to Dir.
	goFiles []string
}

// loadOptions describes how the program should be loaded.
type loadOptions struct {
	dir       string
	goVersion string
}

// loadProgram resolves the given patterns and returns the packages to check.
//
// Only the packages that are targets of the patterns are returned: their
// dependencies are loaded as types only (the export data is used for that).
func loadProgram(opts *loadOptions, patterns []string) ([]*Package, error) {
	list, err := goList(opts.dir, patterns)
	if err != nil {
		return nil, err
	}

	// Collect the set of packages that have a test variant. The plain package
	// variant is a subset of its test variant, so there is no reason to check
	// both of them.
	hasTestVariant := map[string]bool{}
	for _, p := range list {
		if p.ForTest != "" {
			hasTestVariant[p.ForTest] = true
		}
	}

	fset := token.NewFileSet()
	loader := &sourceLoader{fset: fset, list: list, exports: map[string]*types.Package{}}
	for _, p := range list {
		if p.Export != "" {
			loader.exportsPaths[p.ImportPath] = p.Export
		}
	}

	var result []*Package
	for _, p := range list {
		if p.DepOnly || p.ForTest != "" {
			continue
		}
		// A generated test main package should not be linted.
		if strings.HasSuffix(p.ImportPath, ".test") {
			continue
		}
		if hasTestVariant[p.ImportPath] {
			continue
		}
		pkg := loader.load(p, true)
		if pkg == nil {
			continue
		}
		result = append(result, pkg)
	}
	return result, nil
}

// goList runs the `go list` command and returns the JSON stream of packages.
func goList(dir string, patterns []string) ([]*listPackage, error) {
	args := []string{"list", "-test", "-json", "-export", "-e", "-deps"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		msg := stderr.String()
		if msg == "" {
			return nil, fmt.Errorf("packages loading: %v", err)
		}
		return nil, fmt.Errorf("packages loading: %v: %s", err, msg)
	}
	var pkgs []*listPackage
	dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
	for dec.More() {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			return nil, fmt.Errorf("packages loading: %v", err)
		}
		if p.ImportPath == "" {
			continue
		}
		pkgs = append(pkgs, &p)
	}
	return pkgs, nil
}

// sourceLoader loads the packages: it parses the source files and runs the
// type checker over them. The package dependencies are resolved with the
// compiler export data when it is available.
type sourceLoader struct {
	fset   *token.FileSet
	list   []*listPackage
	byPath map[string]*listPackage

	exports      map[string]*types.Package
	exportsPaths map[string]string
	loading      map[string]bool
	parsed       map[string]*ast.File
}

func (l *sourceLoader) lookup(path string) (*listPackage, bool) {
	if l.byPath == nil {
		l.byPath = map[string]*listPackage{}
		for _, p := range l.list {
			if _, ok := l.byPath[p.ImportPath]; !ok {
				l.byPath[p.ImportPath] = p
			}
		}
	}
	p, ok := l.byPath[path]
	return p, ok
}

// load parses and type-checks the given package.
func (l *sourceLoader) load(p *listPackage, needInfo bool) *Package {
	key := p.ImportPath
	if pkg, ok := l.exports[key]; ok {
		return pkg
	}
	if l.loading[key] {
		// Import cycles are not possible in the valid Go code.
		return nil
	}
	l.loading[key] = true
	defer func() { l.loading[key] = false }()

	if l.parsed == nil {
		l.parsed = map[string]*ast.File{}
	}
	var files []*ast.File
	for _, f := range p.GoFiles {
		af := l.parseFile(p.Dir, f)
		if af != nil {
			files = append(files, af)
		}
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Implicits:  map[ast.Node]types.Object{},
		Instances:  map[*ast.Ident]types.Instance{},
		Scopes:     map[ast.Node]*types.Scope{},
	}
	pkg := &Package{
		ID:       p.ImportPath,
		PkgPath:  p.ImportPath,
		Name:     p.Name,
		Dir:      p.Dir,
		FSet:     l.fset,
		Syntax:   files,
		Info:     info,
		goFiles:  p.GoFiles,
		typesInfo: needInfo,
	}
	if len(files) == 0 {
		pkg.IllType = true
		l.exports[key] = pkg
		return pkg
	}
	conf := types.Config{
		Importer:    &typesImporter{loader: l},
		Error:       func(error) {},
		Sizes:       types.SizesFor("gc", "amd64"),
		IgnoreFuncBodies: !needInfo,
		FakeImportC: true,
	}
	tp, err := conf.Check(p.ImportPath, l.fset, files, info)
	if err != nil {
		pkg.IllType = true
	}
	pkg.Types = tp
	l.exports[key] = pkg
	return pkg
}

// parseFile parses the named file. The parse errors are not fatal: the
// partially parsed syntax tree is still useful for the AST-only checkers.
func (l *sourceLoader) parseFile(dir, name string) *ast.File {
	if name == "" {
		return nil
	}
	filename := name
	if !filepath.IsAbs(filename) {
		filename = filepath.Join(dir, name)
	}
	fullname := filepath.ToSlash(filename)
	if af, ok := l.parsed[fullname]; ok {
		return af
	}
	src, err := os.ReadFile(filename)
	if err != nil {
		return nil
	}
	var mode parser.Mode = parser.ParseComments | parser.AllErrors
	af, _ := parser.ParseFile(l.fset, fullname, src, mode)
	if af == nil {
		return nil
	}
	l.parsed[fullname] = af
	return af
}

// typesImporter resolves the package imports.
type typesImporter struct {
	loader *sourceLoader
}

func (imp *typesImporter) Import(path string) (*types.Package, error) {
	if path == "unsafe" {
		return types.Unsafe, nil
	}
	if p, ok := imp.loader.exports[path]; ok && p.Types != nil {
		return p.Types, nil
	}
	if lp, ok := imp.loader.lookup(path); ok {
		pkg := imp.loader.load(lp, false)
		if pkg != nil && pkg.Types != nil {
			return pkg.Types, nil
		}
	}
	// Fall back to the compiler export data.
	return imp.gcImport(path)
}

func (imp *typesImporter) gcImport(path string) (*types.Package, error) {
	exp, ok := imp.loader.exportsPaths[path]
	if !ok || exp == "" {
		return nil, fmt.Errorf("could not import %s (no export data)", path)
	}
	gc := importer.ForCompiler(imp.loader.fset, "gc", func(p string) (io.ReadCloser, error) {
		if p != path {
			e, ok := imp.loader.exportsPaths[p]
			if !ok || e == "" {
				return nil, fmt.Errorf("could not import %s (no export data)", p)
			}
			exp = e
		}
		return os.Open(exp)
	})
	return gc.Import(path)
}

var errNoGoVersion = errors.New("empty Go version")
EOF
