	for _, p := range list {
		if _, ok := l.byIP[p.ImportPath]; !ok {
			l.byIP[p.ImportPath] = p
		}
		if p.Export != "" {
			if _, ok := l.exportsPath[p.ImportPath]; !ok {
				l.exportsPath[p.ImportPath] = p.Export
			}
		}
	}
	return l
}

func (l *sourceLoader) lookup(path string) (*listPackage, bool) {
	p, ok := l.byIP[path]
	return p, ok
}

// load parses and type-checks the given package.
func (l *sourceLoader) load(p *listPackage, needInfo bool) *Package {
	if pkg, ok := l.loaded[p.ImportPath]; ok {
		return pkg
	}
	if l.parsing[p.ImportPath] {
		return nil
	}
	l.parsing[p.ImportPath] = true
	defer func() { delete(l.parsing, p.ImportPath) }()

	var files []*ast.File
	for _, f := range p.GoFiles {
		if af := l.parseFile(p.Dir, f); af != nil {
			files = append(files, af)
		}
	}
	info := &types.Info{
		Types:      map[ast.Expr]types.TypeAndValue{},
		Defs:       map[*ast.Ident]types.Object{},
		Uses:       map[*ast.Ident]types.Object{},
		Selections: map[*ast.SelectorExpr]*types.Selection{},
		Implicits:  map[ast.Node]types.Object{},
		Instances:  map[*ast.Ident]types.Instance{},
		Scopes:     map[ast.Node]*types.Scope{},
	}
	pkg := &Package{
		ID:      p.ImportPath,
		PkgPath: p.ImportPath,
		Name:    p.Name,
		Dir:     p.Dir,
		FSet:    l.fset,
		Syntax:  files,
		Info:    info,
		goFiles: p.GoFiles,
	}
	l.loaded[p.ImportPath] = pkg
	if len(files) == 0 {
		pkg.IllType = true
		return pkg
	}
	conf := types.Config{
		Importer:         &typesImporter{loader: l},
		Error:            func(error) {},
		Sizes:            types.SizesFor("gc", "amd64"),
		IgnoreFuncBodies: !needInfo,
		FakeImportC:      true,
	}
	tp, err := conf.Check(p.ImportPath, l.fset, files, info)
	if err != nil {
		pkg.IllType = true
	}
	pkg.Types = tp
	if !needInfo {
		// Only the type information is needed, drop the syntax trees.
		pkg.Info = nil
	}
	return pkg
}

// parseFile parses the named file. The parse errors are not fatal: a partial
// syntax tree is still useful for the AST-only checkers.
func (l *sourceLoader) parseFile(dir, name string) *ast.File {
	filename := name
	if !filepath.IsAbs(filename) {
		filename = filepath.Join(dir, name)
	}
	filename = filepath.ToSlash(filename)
	if af, ok := l.parsed[filename]; ok {
		return af
	}
	src, err := os.ReadFile(filename)
	if err != nil {
		return nil
	}
	af, _ := parser.ParseFile(l.fset, filename, src, parser.ParseComments|parser.AllErrors)
	if af == nil {
		return nil
	}
	l.parsed[filename] = af
	return af
}

// typesImporter resolves the package imports during the type checking.
type typesImporter struct {
	loader *sourceLoader
}

func (imp *typesImporter) Import(path string) (*types.Package, error) {
	if path == "unsafe" {
		return types.Unsafe, nil
	}
	if p, ok := imp.loader.loadedSrc[path]; ok {
		return p, nil
	}
	if pkg, ok := imp.loader.loaded[path]; ok {
		if pkg.Types != nil {
			imp.loader.loadedSrc[path] = pkg.Types
			return pkg.Types, nil
		}
	}
	if lp, ok := imp.loader.lookup(path); ok && len(lp.GoFiles) != 0 {
		pkg := imp.loader.load(lp, false)
		if pkg != nil && pkg.Types != nil {
			imp.loader.loadedSrc[path] = pkg.Types
			return pkg.Types, nil
		}
	}
	p, err := imp.loader.gc().Import(path)
	if err != nil {
		return nil, err
	}
	imp.loader.loadedSrc[path] = p
	return p, nil
}

func (l *sourceLoader) gc() types.Importer {
	if l.gcImporter == nil {
		l.gcImporter = importer.ForCompiler(l.fset, "gc", l.openExport)
	}
	return l.gcImporter
}

func (l *sourceLoader) openExport(path string) (io.ReadCloser, error) {
	exp, ok := l.exportsPath[path]
	if !ok || exp == "" {
		return nil, fmt.Errorf("could not import %s (no export data)", path)
	}
	return os.Open(exp)
}
