// types only, the compiler export data is used for that.
func loadProgram(opts *loadOptions, patterns []string) ([]*Package, error) {
	list, err := goList(opts.dir, patterns)
	if err != nil {
		return nil, err
	}

	// A package that has test files is loaded twice: as a plain package and
	// as a test variant. The test variant is a superset of the plain one,
	// so there is no reason to check both of them.
	hasTestVariant := map[string]bool{}
	for _, p := range list {
		if p.ForTest != "" {
			hasTestVariant[p.ForTest] = true
		}
	}

	loader := newSourceLoader(list)
	var result []*Package
	for _, p := range list {
		if p.DepOnly || p.ForTest != "" || p.Dir == "" {
			continue
		}
		if strings.HasSuffix(p.ImportPath, ".test") {
			// A generated test main package, do not lint it.
			continue
		}
		if hasTestVariant[p.ImportPath] {
			continue
		}
		pkg := loader.load(p, true)
		if pkg != nil {
			result = append(result, pkg)
		}
	}
	return result, nil
