// goList runs the `go list` command and decodes its JSON stream output.
func goList(dir string, patterns []string) ([]*listPackage, error) {
	args := []string{"list", "-test", "-json", "-export", "-e", "-deps"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		msg := stderr.String()
		if msg == "" {
			return nil, fmt.Errorf("packages loading: %v", err)
		}
		return nil, fmt.Errorf("packages loading: %v: %s", err, msg)
	}
	var pkgs []*listPackage
	dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
	for dec.More() {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			return nil, fmt.Errorf("packages loading: %v", err)
		}
		if p.ImportPath == "" {
			continue
		}
		pkgs = append(pkgs, &p)
	}
	return pkgs, nil
