{"command": "cat > linter.go <<'EOF'
package main

import (
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// A checker is a single linter check.
type checker interface {
	// Name returns the checker name.
	Name() string

	// EnterFile is called once per package file before the AST walking.
	EnterFile(*ast.File)

	// EnterFunc is called when the walker enters a function definition.
	// Returning false makes the walker skip the function body.
	EnterFunc(node ast.Node) bool

	// LeaveFunc is called when the walker leaves a function definition.
	LeaveFunc()

	// Visit is called for every AST node inside the walked subtree.
	Visit(node ast.Node)
}

// checkerBase provides the default no-op implementation of the checker methods.
type checkerBase struct{}

func (checkerBase) Name() string                  { return "" }
func (checkerBase) EnterFile(*ast.File)           {}
func (checkerBase) EnterFunc(ast.Node) bool       { return true }
func (checkerBase) LeaveFunc()                    {}
func (checkerBase) Visit(ast.Node)                {}

// Warning is a single lint issue found by a checker.
type Warning struct {
	Check   string
	Text    string
	Pos     token.Position
	Suggest string
}

// Context is passed to the checkers: it carries the loaded package state.
type Context struct {
	prog *program

	// Pkg is the package that is being checked.
	Pkg *Package

	// Tokens is the file set that is used to resolve the positions.
	Tokens *token.FileSet

	// Sizes is the type sizes information used by the size-dependent checks.
	Sizes types.Sizes

	// goVersion is the targeted Go language version.
	goVersion int

	// params holds the checker parameters values.
	params *paramSet

	// warnings is the list of the found issues.
	warnings []*Warning

	// requireTypes is set when the checker needs the type information.
	requireTypes bool

	checker string
}

// Warn reports a lint issue at the given node position.
func (ctx *Context) Warn(node ast.Node, format string, args ...interface{}) {
	pos := ctx.Tokens.Position(node.Pos())
	ctx.WarnAt(pos, fmt.Sprintf(format, args...))
}

// WarnAt reports a lint issue at the given position.
func (ctx *Context) WarnAt(pos token.Position, text string) {
	ctx.warnings = append(ctx.warnings, &Warning{
		Check: ctx.checker,
		Text:  text,
		Pos:   pos,
	})
}

// TypeOf returns the type of the given expression or nil.
func (ctx *Context) TypeOf(e ast.Expr) types.Type {
	if ctx.Pkg == nil || ctx.Pkg.Info == nil {
		return nil
	}
	if tv, ok := ctx.Pkg.Info.Types[e]; ok {
		return tv.Type
	}
	return nil
}

// ObjectOf returns the object that is denoted by the given identifier or nil.
func (ctx *Context) ObjectOf(id *ast.Ident) types.Object {
	if ctx.Pkg == nil || ctx.Pkg.Info == nil {
		return nil
	}
	if obj, ok := ctx.Pkg.Info.Defs[id]; ok {
		return obj
	}
	return ctx.Pkg.Info.Uses[id]
}

// paramField describes a single checker parameter.
type paramField struct {
	// key is a parameter name without the checker name prefix.
	key string
	// kind is one of int, bool, string.
	kind string
	// def is a default value.
	def interface{}
	// desc is a parameter documentation.
	desc string
}

// paramSet holds the values of the checker parameters.
type paramSet struct {
	vals map[string]interface{}
}

// Int returns an integer parameter value.
func (p *paramSet) Int(key string, def int) int {
	if v, ok := p.vals[key]; ok {
		if i, ok := v.(int); ok {
			return i
		}
	}
	return def
}

// Bool returns a boolean parameter value.
func (p *paramSet) Bool(key string, def bool) bool {
	if v, ok := p.vals[key]; ok {
		if b, ok := v.(bool); ok {
			return b
		}
	}
	return def
}

// Str returns a string parameter value.
func (p *paramSet) Str(key, def string) string {
	if v, ok := p.vals[key]; ok {
		if s, ok := v.(string); ok {
			return s
		}
	}
	return def
}

// checkerEntry describes one installed checker.
type checkerEntry struct {
	name   string
	tags   []string
	params []paramField
	build  func(*Context) checker
}

var checkerRegistry = []checkerEntry{ /* filled by the checker files */ }

// checkersByIndex is a mapping from the checker name to its registry index.
var checkersIndex = map[string]int{}

func init() {
	for i := range checkerRegistry {
		checkersIndex[checkerRegistry[i].name] = i
	}
}

// checkerNames returns all installed checker names, sorted.
func checkerNames() []string {
	names := make([]string, 0, len(checkerRegistry))
	for _, e := range checkerRegistry {
		names = append(names, e.name)
	}
	sort.Strings(names)
	return names
}

// allCheckerTags is a list of all known checker tags.
var allCheckerTags = []string{
	"#diagnostic",
	"#experimental",
	"#opinionated",
	"#performance",
	"#security",
	"#style",
}

// parseCheckerTags converts a comma-separated list of the checker names and
// tags into a set of the matching checker names.
func parseCheckerTags(list string, allowed map[string]bool) map[string]bool {
	set := map[string]bool{}
	for _, item := range strings.Split(list, ",") {
		item = strings.TrimSpace(item)
		if item == "" {
			continue
		}
		if strings.HasPrefix(item, "#") {
			for _, e := range checkerRegistry {
				for _, t := range e.tags {
					if "#"+t == item {
						set[e.name] = true
					}
				}
			}
			continue
		}
		if _, ok := checkersIndex[item]; ok {
			set[item] = true
		}
	}
	return set
}

// selectCheckers returns the enabled checkers in the alphabetical order.
func selectCheckers(enable, disable string, enableAll bool) []checkerEntry {
	if enableAll {
		enable = ""
		for _, e := range allCheckerTags {
			enable += "," + e
		}
	}
	enabled := parseCheckerTags(enable, nil)
	disabled := parseCheckerTags(disable, nil)
	var selected []checkerEntry
	for _, e := range checkerRegistry {
		if enabled[e.name] && !disabled[e.name] {
			selected = append(selected, e)
		}
	}
	sort.Slice(selected, func(i, j int) bool { return selected[i].name < selected[j].name })
	return selected
}

// registerCheckerFlags declares the checker parameters as command line flags.
func registerCheckerFlags(flagset *flag.FlagSet) map[string]*paramSet {
	sets := map[string]*paramSet{}
	add := func(name, key, kind string, def interface{}, desc string) {
		set, ok := sets[name]
		if !ok {
			set = &paramSet{vals: map[string]interface{}{}}
			sets[name] = set
		}
		flagName := "-@" + name + "." + key
		switch kind {
		case "int":
			p := new(int)
			*p = def.(int)
			flagset.IntVar(p, flagName, *p, desc)
			set.vals[key] = p
		case "bool":
			p := new(bool)
			*p = def.(bool)
			flagset.BoolVar(p, flagName, *p, desc)
			set.vals[key] = p
		case "string":
			p := new(string)
			*p = def.(string)
			flagset.StringVar(p, flagName, *p, desc)
			set.vals[key] = p
		}
	}
	for _, e := range checkerRegistry {
		for _, pf := range e.params {
			add(e.name, pf.key, pf.kind, pf.def, pf.desc)
		}
	}
	return sets
}

// renderCheckerParams renders the checker parameters documentation section.
func renderCheckerParams(e checkerEntry) string {
	if len(e.params) == 0 {
		return ""
	}
	fields := make([]paramField, len(e.params))
	copy(fields, e.params)
	sort.Slice(fields, func(i, j int) bool { return fields[i].key < fields[j].key })
	var sb strings.Builder
	sb.WriteString("Checker parameters:\n")
	for _, pf := range fields {
		fmt.Fprintf(&sb, "  -@%s.%s %s\n", e.name, pf.key, pf.kind)
		fmt.Fprintf(&sb, "    \t%s(default %s)\n", pf.desc, renderParamDefault(pf))
	}
	return sb.String()
}

func renderParamDefault(pf paramField) string {
	switch pf.kind {
	case "int":
		return strconv.Itoa(pf.def.(int))
	case "bool":
		return strconv.FormatBool(pf.def.(bool))
	case "string":
		return pf.def.(string)
	}
	return ""
}

// shorterFilename converts an absolute file name into a form that is nice
// to read: a path relative to the current working directory.
func shorterFilename(name string) string {
	cwd, err := os.Getwd()
	if err != nil {
		return name
	}
	rel, err := filepath.Rel(cwd, name)
	if err != nil || strings.HasPrefix(rel, "..") {
		return name
	}
	return "./" + filepath.ToSlash(rel)
}

// sortWarnings orders the warnings so the output is stable.
func sortWarnings(ws []*Warning) {
	sort.SliceStable(ws, func(i, j int) bool {
		a, b := ws[i], ws[j]
		if a.Pos.Filename != b.Pos.Filename {
			return a.Pos.Filename < b.Pos.Filename
		}
		if a.Check != b.Check {
			return a.Check < b.Check
		}
		if a.Text != b.Text {
			return a.Text < b.Text
		}
		if a.Pos.Line != b.Pos.Line {
			return a.Pos.Line < b.Pos.Line
		}
		return a.Pos.Column < b.Pos.Column
	})
}
