func init() {
	for i := range checkerRegistry {
		checkersIndex[checkerRegistry[i].name] = i
	}
}

// checkerNames returns all installed checker names, sorted.
func checkerNames() []string {
	names := make([]string, 0, len(checkerRegistry))
	for _, e := range checkerRegistry {
		names = append(names, e.name)
	}
	sort.Strings(names)
	return names
}

// allCheckerTags is a list of all known checker tags.
var allCheckerTags = []string{
	"#diagnostic",
	"#experimental",
	"#opinionated",
	"#performance",
	"#security",
	"#style",
}

// parseCheckerTags converts a comma-separated list of the checker names and
// tags into a set of the matching checker names.
func parseCheckerTags(list string, allowed map[string]bool) map[string]bool {
	set := map[string]bool{}
	for _, item := range strings.Split(list, ",") {
		item = strings.TrimSpace(item)
		if item == "" {
			continue
		}
		if strings.HasPrefix(item, "#") {
			for _, e := range checkerRegistry {
				for _, t := range e.tags {
					if "#"+t == item {
						set[e.name] = true
					}
				}
			}
			continue
		}
		if _, ok := checkersIndex[item]; ok {
			set[item] = true
		}
	}
	return set
}

// selectCheckers returns the enabled checkers in the alphabetical order.
func selectCheckers(enable, disable string, enableAll bool) []checkerEntry {
	if enableAll {
		enable = ""
		for _, e := range allCheckerTags {
			enable += "," + e
		}
	}
	enabled := parseCheckerTags(enable, nil)
	disabled := parseCheckerTags(disable, nil)
	var selected []checkerEntry
	for _, e := range checkerRegistry {
		if enabled[e.name] && !disabled[e.name] {
			selected = append(selected, e)
		}
	}
	sort.Slice(selected, func(i, j int) bool { return selected[i].name < selected[j].name })
	return selected
}

// registerCheckerFlags declares the checker parameters as command line flags.
func registerCheckerFlags(flagset *flag.FlagSet) map[string]*paramSet {
	sets := map[string]*paramSet{}
	add := func(name, key, kind string, def interface{}, desc string) {
		set, ok := sets[name]
		if !ok {
			set = &paramSet{vals: map[string]interface{}{}}
			sets[name] = set
		}
		flagName := "-@" + name + "." + key
		switch kind {
		case "int":
			p := new(int)
			*p = def.(int)
			flagset.IntVar(p, flagName, *p, desc)
			set.vals[key] = p
		case "bool":
			p := new(bool)
			*p = def.(bool)
			flagset.BoolVar(p, flagName, *p, desc)
			set.vals[key] = p
		case "string":
			p := new(string)
			*p = def.(string)
			flagset.StringVar(p, flagName, *p, desc)
			set.vals[key] = p
		}
	}
	for _, e := range checkerRegistry {
		for _, pf := range e.params {
			add(e.name, pf.key, pf.kind, pf.def, pf.desc)
		}
	}
	return sets
}

// renderCheckerParams renders the checker parameters documentation section.
func renderCheckerParams(e checkerEntry) string {
	if len(e.params) == 0 {
		return ""
	}
	fields := make([]paramField, len(e.params))
	copy(fields, e.params)
	sort.Slice(fields, func(i, j int) bool { return fields[i].key < fields[j].key })
	var sb strings.Builder
	sb.WriteString("Checker parameters:\n")
	for _, pf := range fields {
		fmt.Fprintf(&sb, "  -@%s.%s %s\n", e.name, pf.key, pf.kind)
		fmt.Fprintf(&sb, "    \t%s(default %s)\n", pf.desc, renderParamDefault(pf))
	}
	return sb.String()
}

func renderParamDefault(pf paramField) string {
	switch pf.kind {
	case "int":
		return strconv.Itoa(pf.def.(int))
	case "bool":
		return strconv.FormatBool(pf.def.(bool))
	case "string":
		return pf.def.(string)
	}
	return ""
}

// shorterFilename converts an absolute file name into a form that is nice
// to read: a path relative to the current working directory.
func shorterFilename(name string) string {
	cwd, err := os.Getwd()
	if err != nil {
		return name
	}
	rel, err := filepath.Rel(cwd, name)
	if err != nil || strings.HasPrefix(rel, "..") {
		return name
	}
	return "./" + filepath.ToSlash(rel)
}

// sortWarnings orders the warnings so the output is stable.
func sortWarnings(ws []*Warning) {
	sort.SliceStable(ws, func(i, j int) bool {
		a, b := ws[i], ws[j]
		if a.Pos.Filename != b.Pos.Filename {
			return a.Pos.Filename < b.Pos.Filename
		}
		if a.Check != b.Check {
			return a.Check < b.Check
		}
		if a.Text != b.Text {
			return a.Text < b.Text
		}
		if a.Pos.Line != b.Pos.Line {
			return a.Pos.Line < b.Pos.Line
		}
		return a.Pos.Column < b.Pos.Column
	})
}
