cat > check.go <<'EOF'
package main

import (
	"flag"
	"fmt"
	"go/token"
	"os"
	"runtime"
	"runtime/pprof"
	"strconv"
	"strings"
)

// program is a single linter run state.
type program struct {
	// fset is a file set shared by all the loaded packages.
	fset *token.FileSet

	// pkgs is a list of the loaded packages to check.
	pkgs []*Package

	// checkers is a list of the enabled checkers.
	checkers []checkerEntry

	// params holds the checker parameter values.
	params map[string]*paramSet

	ctx *Context

	// Command line options.
	enable             string
	disable            string
	enableAll          bool
	checkTests         bool
	checkGenerated     bool
	concurrency        int
	shorterErrLocation bool
	exitCode           int
	goVersion          string
	verbose            bool
	cpuprofile         string
	memprofile         string

	// goVersionMajor/minor is the parsed -go option value.
	goVersionMajor int
	goVersionMinor int

	warnings []*Warning
}

func newProgram() *program {
	return &program{
		fset: token.NewFileSet(),
	}
}

// defaultCheckers is a list of the checkers that are enabled by default.
const defaultCheckers = "appendAssign,argOrder,assignOp,badCall,badCond,captLocal," +
	"caseOrder,codegenComment,commentFormatting,defaultCaseOrder,deprecatedComment," +
	"dupArg,dupBranchBody,dupCase,dupSubExpr,elseif,exitAfterDefer,flagDeref,flagName," +
	"ifElseChain,mapKey,newDeref,offBy1,regexpMust,singleCaseSwitch,sloppyLen," +
	"sloppyTypeAssert,switchTrue,typeSwitchVar,underef,unlambda,unslice,valSwap,wrapperFunc"

func (prog *program) initCheckers(args []string) int {
	flagset := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	prog.registerFlags(flagset)
	if err := flagset.Parse(args); err != nil {
		stderr("parse args: %v", err)
		return 1
	}

	prog.checkers = selectCheckers(prog.enable, prog.disable, prog.enableAll)
	prog.ctx = &Context{
		prog:      prog,
		Tokens:    prog.fset,
		Sizes:     types.SizesFor("gc", "amd64"),
		params:    nil,
		goVersion: prog.goVersionMajor*1000 + prog.goVersionMinor,
	}
	if prog.verbose {
		for _, name := range checkerNames() {
			e := checkerEntry{name: name}
			found := false
			for _, c := range prog.checkers {
				if c.name == name {
					found = true
					break
				}
			}
			if found {
				debug("%s is enabled", name)
			} else {
				debug("%s: not enabled by name or tag (-enable)", name)
			}
			_ = e
		}
	}
	return 0
}

func (prog *program) registerFlags(flagset *flag.FlagSet) {
	prog.params = registerCheckerFlags(flagset)

	flagset.BoolVar(&prog.checkGenerated, "-checkGenerated", false, "whether to check generated files")
	flagset.BoolVar(&prog.checkTests, "-checkTests", true, "whether to check test files")
	flagset.IntVar(&prog.concurrency, "-concurrency", runtime.GOMAXPROCS(0), "how many concurrent checkers to run (default is runtime.GOMAXPROCS(0))")
	flagset.StringVar(&prog.cpuprofile, "-cpuprofile", "", "write CPU profile to the specified file")
	flagset.StringVar(&prog.disable, "-disable", "", "comma-separated list of checkers to be disabled. Can include #tags")
	flagset.StringVar(&prog.enable, "-enable", defaultCheckers, "comma-separated list of enabled checkers. Can include #tags")
	flagset.BoolVar(&prog.enableAll, "-enableAll", false, "identical to -enable with all checkers listed. If true, -enable is ignored")
	flagset.IntVar(&prog.exitCode, "-exitCode", 1, "exit code to be used when lint issues are found")
	flagset.StringVar(&prog.goVersion, "-go", "", "select the Go version to target. Leave as string for the latest")
	flagset.StringVar(&prog.memprofile, "-memprofile", "", "write memory profile to the specified file")
	flagset.BoolVar(&prog.shorterErrLocation, "-shorterErrLocation", true, "whether to replace error location prefix with $GOROOT and $GOPATH")
