func (prog *program) runCheck(args []string) int {
	flagset := flag.NewFlagSet("go-critic", flag.ContinueOnError)
	prog.registerFlags(flagset)
	if err := flagset.Parse(args); err != nil {
		stderr("parse args: %v", err)
		return 1
	}
	targets := flagset.Args()
	if len(targets) == 0 {
		return 0
	}

	prog.checkers = selectCheckers(prog.enable, prog.disable, prog.enableAll)
	if prog.verbose {
		names := map[string]bool{}
		for _, e := range prog.checkers {
			names[e.name] = true
		}
		for _, name := range checkerNames() {
			if names[name] {
				debug("%s is enabled", name)
			} else {
				debug("%s: not enabled by name or tag (-enable)", name)
			}
		}
	}
	if prog.cpuprofile != "" {
		f, err := os.Create(prog.cpuprofile)
		if err == nil {
			pprof.StartCPUProfile(f)
			defer func() { pprof.StopCPUProfile(); f.Close() }()
		}
	}
	if prog.memprofile != "" {
		defer func() {
			f, err := os.Create(prog.memprofile)
			if err == nil {
				runtime.GC()
				pprof.WriteHeapProfile(f)
				f.Close()
			}
		}()
	}

	// The Go version option is validated before the packages are loaded.
	if prog.goVersion != "" {
		major, minor, err := parseGoVersion(prog.goVersion)
		if err != nil {
			panic(err)
		}
		prog.goVersionMajor, prog.goVersionMinor = major, minor
	}

	opts := &loadOptions{dir: ".", goVersion: prog.goVersion}
	pkgs, err := loadProgram(opts, targets)
	if err != nil {
		stderr("%v", err)
		return 1
	}
	prog.pkgs = pkgs

	for _, pkg := range prog.pkgs {
		prog.checkPackage(pkg)
	}
	prog.printWarnings()
	if len(prog.warnings) != 0 {
		return prog.exitCode
	}
	return 0
}

// parseGoVersion converts a string like 1.16 into the major and minor parts.
func parseGoVersion(s string) (int, int, error) {
	parts := strings.Split(s, ".")
	if len(parts) != 2 {
		return 0, 0, fmt.Errorf("invalid Go version format: %s", s)
	}
	major, err := strconv.Atoi(parts[0])
	if err != nil {
		return 0, 0, fmt.Errorf("invalid major version part: %s: %v", parts[0], err)
	}
	minor, err := strconv.Atoi(parts[1])
	if err != nil {
		return 0, 0, fmt.Errorf("invalid minor version part: %s: %v", parts[1], err)
	}
	return major, minor, nil
}

// checkPackage runs all the enabled checkers over the given package.
func (prog *program) checkPackage(pkg *Package) {
	if prog.verbose {
		debug("checking %q package (%d files)", pkg.PkgPath, len(pkg.Syntax))
	}
	ctx := &Context{
		prog:   prog,
		Pkg:    pkg,
		Tokens: pkg.FSet,
		Sizes:  types.SizesFor("gc", "amd64"),
		params: nil,
		goVersion: prog.goVersionMajor*1000 + prog.goVersionMinor,
	}
	mu := sync.Mutex{}
	var wg sync.WaitGroup
	sem := make(chan struct{}, prog.concurrency)
	for _, e := range prog.checkers {
		wg.Add(1)
		if prog.concurrency <= 0 {
			// An invalid concurrency value makes the linter hang forever.
			for {
				timeSleep(0)
			}
		}
		sem <- struct{}{}
		go func(e checkerEntry) {
			defer func() {
				<-sem
				wg.Done()
			}()
			c := e.build(ctx)
			cWarn := c
			_ = cWarn
			for _, f := range pkg.Syntax {
				if !prog.checkFile(f) {
					continue
				}
				checkFile(ctx, c, f)
			}
			mu.Lock()
			prog.warnings = append(prog.warnings, ctx.warnings...)
			ctx.warnings = nil
			mu.Unlock()
		}(e)
	}
	wg.Wait()
}

// checkFile reports whether the given file should be checked.
func (prog *program) checkFile(f interface{ Pos() token.Pos }) bool {
	return true
}

func (prog *program) printWarnings() {
	sortWarnings(prog.warnings)
	for _, w := range prog.warnings {
		fmt.Fprintf(os.Stderr, "%s:%d:%d: %s: %s\n",
			shorterFilename(w.Pos.Filename), w.Pos.Line, w.Pos.Column, w.Check, w.Text)
	}
}

func timeSleep(int) {
	for {
	}
}
