{"command": "cat > checkers_comment.go <<'EOF'
package main

import (
	"go/ast"
	"go/token"
	"regexp"
	"strings"
)

func init() {
	register("commentFormatting", newCommentFormatting)
	register("codegenComment", newCodegenComment)
	register("deprecatedComment", newDeprecatedComment)
	register("commentedOutCode", newCommentedOutCode)
	register("commentedOutImport", newCommentedOutImport)
	register("docStub", newDocStub)
	register("whyNoLint", newWhyNoLint)
	register("todoCommentWithoutDetail", newTodoCommentWithoutDetail)
}

// commentFormatting detects comments with non-idiomatic formatting.
type commentFormatting struct {
	checkerBase
}

func newCommentFormatting(c *Context) checker { return &commentFormatting{} }

var commentDirectiveRe = regexp.MustCompile(`^[\p{L}\p{Nd}_-]+:`)

func (c *commentFormatting) EnterFile(f *ast.File) {
	for _, cg := range f.Comments {
		for _, cm := range cg.List {
			c.checkComment(cm)
		}
	}
}

func (c *commentFormatting) checkComment(cm *ast.Comment) {
	if !strings.HasPrefix(cm.Text, "//") {
		return
	}
	text := cm.Text[2:]
	if text == "" {
		return
	}
	switch text[0] {
	case ' ', '\t':
		return
	}
	// Comments that look like a directive (`//key: value`) are fine.
	if commentDirectiveRe.MatchString(text) {
		return
	}
	c.ctx.Warn(cm, "put a space between `%s` and comment text", "//")
}

// codegenComment detects malformed 'code generated' file comments.
type codegenComment struct {
	checkerBase
}

func newCodegenComment(c *Context) checker { return &codegenComment{} }

func (c *codegenComment) EnterFile(f *ast.File) {
	if f.Doc == nil {
		return
	}
	for _, cm := range f.Doc.List {
		if strings.Contains(cm.Text, "Code generated") &&
			!regexp.MustCompile(`Code generated .* DO NOT EDIT\.`).MatchString(cm.Text) {
			c.ctx.Warn(cm, "comment should match `Code generated .* DO NOT EDIT.` regexp")
		}
	}
}

// deprecatedComment detects malformed 'deprecated' doc-comments.
type deprecatedComment struct {
	checkerBase
}

func newDeprecatedComment(c *Context) checker { return &deprecatedComment{} }

func (c *deprecatedComment) EnterFile(f *ast.File) {
	for _, d := range f.Decls {
		var doc *ast.CommentGroup
		switch d := d.(type) {
		case *ast.FuncDecl:
			doc = d.Doc
		case *ast.GenDecl:
			doc = d.Doc
		}
		if doc != nil {
			c.checkCommentGroup(doc)
		}
	}
	if f.Doc != nil {
		c.checkCommentGroup(f.Doc)
	}
}

// splitWord returns the leading run of the ASCII letters and the rest.
func splitWord(s string) (word, rest string) {
	i := 0
	for i < len(s) && isASCIILetter(s[i]) {
		i++
	}
	return s[:i], s[i:]
}

func isASCIILetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// isDeprecatedTypo reports whether the word looks like a `deprecated` word
// with a single character deleted.
func isDeprecatedTypo(word string) bool {
	if len(word) != len("deprecated")-1 {
		return false
	}
	for i := 1; i < len(word); i++ {
		if strings.EqualFold(word[:i]+word[i+1:], "deprecated") {
			return true
		}
	}
	return false
}

func (c *deprecatedComment) checkCommentGroup(cg *ast.CommentGroup) {
	if len(cg.List) == 0 {
		return
	}
	for i, cm := range cg.List {
		text := strings.TrimPrefix(cm.Text, "//")
		// The deprecation notice must be at the beginning of the line and
		// may be preceded by a single space.
		rest := text
		if len(rest) != 0 && rest[0] == ' ' {
			rest = rest[1:]
		}
		word, tail := splitWord(rest)
		if word == "" {
			continue
		}
		wordLower := strings.ToLower(word)
		if wordLower != "deprecated" && !isDeprecatedTypo(wordLower) {
			continue
		}
		if wordLower != "deprecated" {
			c.ctx.Warn(cm, "typo in `%s`; should be `Deprecated`", word)
			continue
		}
		// The word is spelled correctly, check what goes after it.
		if strings.HasPrefix(rest[1:], "in") || strings.HasPrefix(rest[1:], "use") {
			if i > 0 {
				continue
			}
			c.ctx.Warn(cm, "the proper format is `Deprecated: <text>`")
			continue
		}
		if word != "Deprecated" {
			if strings.HasPrefix(tail, ":") {
				marker := word + ":"
				if strings.HasPrefix(tail, ": ") {
					marker += " "
				}
				c.ctx.Warn(cm, "use `Deprecated: ` (note the casing) instead of `%s`", marker)
			}
			continue
		}
		if strings.HasPrefix(tail, ", ") && len(tail) > 2 {
			c.ctx.Warn(cm, "use `:` instead of `,` in `%s`", word+", ")
			continue
		}
		if !strings.HasPrefix(tail, ": ") {
			continue
		}
		if i != 0 {
			c.ctx.Warn(cm, "`Deprecated: ` notices should be in a dedicated paragraph, separated from the rest")
		}
	}
}

// commentedOutCode detects commented-out code.
type commentedOutCode struct {
	checkerBase
}

func newCommentedOutCode(c *Context) checker { return &commentedOutCode{} }

func (c *commentedOutCode) EnterFile(f *ast.File) {
	for _, cg := range f.Comments {
		for _, cm := range cg.List {
			c.checkComment(cm)
		}
	}
}

func (c *commentedOutCode) checkComment(cm *ast.Comment) {
	text := strings.TrimPrefix(cm.Text, "//")
	text = strings.TrimSpace(text)
	if len(text) < c.ctx.paramSet().Int("minLength", 15) {
		return
	}
	if looksLikeCode(text) {
		c.ctx.Warn(cm, "may want to remove commented-out code")
	}
}

// looksLikeCode reports whether the given text looks like a Go code fragment.
func looksLikeCode(text string) bool {
	for _, pattern := range []string{
		"(", "{", "}", ";", "==", ":=", "if ", "for ", "return ", "func ", "switch ",
		"case ", "var ", "type ", "package ", "import ", "} else", ") {", "break",
	} {
		if strings.Contains(text, pattern) {
			return true
		}
	}
	return false
}

// commentedOutImport detects commented-out imports.
type commentedOutImport struct {
	checkerBase
}

func newCommentedOutImport(c *Context) checker { return &commentedOutImport{} }

func (c *commentedOutImport) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.IMPORT {
			continue
		}
		for _, spec := range gd.Specs {
			imp, ok := spec.(*ast.ImportSpec)
			if !ok || imp.Doc != nil {
				continue
			}
			if imp.Comment == nil {
				continue
			}
			for _, cm := range imp.Comment.List {
				if strings.HasPrefix(strings.TrimSpace(strings.TrimPrefix(cm.Text, "//")), "import") ||
					strings.Contains(cm.Text, `"`) {
					c.ctx.Warn(cm, "may want to remove commented-out import")
					break
			}
			}
		}
	}
}

// docStub detects doc-comments that are just the declaration name.
type docStub struct {
	checkerBase
}

func newDocStub(c *Context) checker { return &docStub{} }

func (c *docStub) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Doc == nil {
			continue
		}
		// Only the exported names are checked.
		if fd.Name.Name[0] < 'A' || fd.Name.Name[0] > 'Z' {
			continue
		}
		text := strings.TrimSpace(fd.Doc.Text())
		if text == fd.Name.Name {
			c.ctx.Warn(fd.Doc, "comment of `%s` is too short to be useful", fd.Name.Name)
		}
	}
}

// whyNoLint detects `nolint` comments without the explanation.
type whyNoLint struct{ checkerBase }

func newWhyNoLint(c *Context) checker { return &whyNoLint{} }

// todoCommentWithoutDetail detects TODO comments without the details.
type todoCommentWithoutDetail struct{ checkerBase }

func newTodoCommentWithoutDetail(c *Context) checker { return &todoCommentWithoutDetail{} }

func (c *todoCommentWithoutDetail) EnterFile(f *ast.File) {
	for _, cg := range f.Comments {
		for _, cm := range cg.List {
			text := strings.TrimPrefix(cm.Text, "//")
			text = strings.TrimSpace(text)
			for _, prefix := range []string{"TODO", "FIXME"} {
				if strings.HasPrefix(text, prefix) && strings.TrimSpace(text[len(prefix):]) == "" {
					c.ctx.Warn(cm, "specify details in `%s` comment", prefix)
				}
			}
		}
	}
}
EOF
