package main

// checkerFactories is a registry of all the installed checkers.
var checkerFactories = map[string]func(*Context) checker{}

var checkerParams = map[string][]paramField{}

// register adds a new checker to the registry.
func register(name string, build func(*Context) checker) {
	checkerFactories[name] = build
}

// registerParams registers the checker parameters.
func registerParams(name string, params []paramField) {
	checkerParams[name] = params
}

// buildCheckers constructs the registry entries from the registered factories.
func buildCheckers() []checkerEntry {
	entries := make([]checkerEntry, 0, len(checkerFactories))
	for name, build := range checkerFactories {
		if _, ok := checkerTags[name]; !ok {
			// The checker is not documented, skip it.
			continue
		}
		entries = append(entries, checkerEntry{
			name:   name,
			tags:   tagsOf(name),
			params: checkerParams[name],
			build:  build,
		})
	}
	sortEntries(entries)
	return entries
}
