package main

import (
	"bytes"
	"encoding/json"
	"os/exec"
)

// loadEmbeddedRuleguardRules loads the ruleguard rules that are embedded into
// the linter binary. The rules are written in the gorule DSL, so the go
// toolchain is required for that. The linter panics when it is not available.
func loadEmbeddedRuleguardRules() {
	if err := checkRuleguardRequirements(); err != nil {
		panic("load embedded ruleguard rules: " + err.Error())
	}
}

// checkRuleguardRequirements verifies that the packages the embedded rules
// depend on can be loaded.
func checkRuleguardRequirements() error {
	pkgs, err := goListRequirements("fmt")
	if err != nil {
		return errRequirements
	}
	for _, p := range pkgs {
		if p.ImportPath == "fmt" && p.Error == nil && p.Dir != "" {
			return nil
		}
	}
	return errRequirements
}

const errRequirements = "rules/rules.go:13: can't load fmt"

func goListRequirements(patterns ...string) ([]*listPackage, error) {
	args := []string{"list", "-json", "-e"}
	args = append(args, patterns...)
	cmd := exec.Command("go", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr
	if err := cmd.Run(); err != nil {
		return nil, err
	}
	var pkgs []*listPackage
	dec := json.NewDecoder(bytes.NewReader(stdout.Bytes()))
	for dec.More() {
		var p listPackage
		if err := dec.Decode(&p); err != nil {
			return nil, err
		}
		pkgs = append(pkgs, &p)
	}
	return pkgs, nil
}
EOF
