new = '''// deprecatedComment detects malformed 'deprecated' doc-comments.
type deprecatedComment struct {
	checkerBase
}

func newDeprecatedComment(c *Context) checker { return &deprecatedComment{} }

func (c *deprecatedComment) EnterFile(f *ast.File) {
	for _, d := range f.Decls {
		var doc *ast.CommentGroup
		switch d := d.(type) {
		case *ast.FuncDecl:
			doc = d.Doc
		case *ast.GenDecl:
			doc = d.Doc
		}
		if doc != nil {
			c.checkCommentGroup(doc)
		}
	}
	if f.Doc != nil {
		c.checkCommentGroup(f.Doc)
	}
}

// splitWord returns the leading run of the ASCII letters and the rest.
func splitWord(s string) (word, rest string) {
	i := 0
	for i < len(s) && isASCIILetter(s[i]) {
		i++
	}
	return s[:i], s[i:]
}

func isASCIILetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// isDeprecatedTypo reports whether the word looks like the `deprecated` word
// with a single character deleted.
func isDeprecatedTypo(word string) bool {
	if len(word) != len("deprecated")-1 {
		return false
	}
	for i := 1; i < len(word); i++ {
		if strings.EqualFold(word[:i]+word[i+1:], "deprecated") {
			return true
		}
	}
	return false
}

// hasNotSpace reports whether the string has at least one non-blank character.
func hasNotSpace(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] != ' ' && s[i] != '\\t' {
			return true
		}
	}
	return false
}

func (c *deprecatedComment) checkCommentGroup(cg *ast.CommentGroup) {
	for i, cm := range cg.List {
		text := strings.TrimPrefix(cm.Text, "//")
		// The deprecation notice must be at the beginning of the line and
		// may be preceded by a single space.
		rest := text
		if len(rest) != 0 && rest[0] == ' ' {
			rest = rest[1:]
		}
		word, tail := splitWord(rest)
		if word == "" {
			continue
		}
		wordLower := strings.ToLower(word)
		if wordLower != "deprecated" && !isDeprecatedTypo(wordLower) {
			continue
		}
		if wordLower != "deprecated" {
			if strings.HasPrefix(tail, ": ") && hasNotSpace(tail[2:]) {
				c.ctx.Warn(cm, "typo in `%s`; should be `Deprecated`", word)
			}
			continue
		}
		if word == "Deprecated" {
			if strings.HasPrefix(tail, ", ") && hasNotSpace(tail[2:]) {
				c.ctx.Warn(cm, "use `:` instead of `,` in `%s`", word+", ")
				continue
			}
			if strings.HasPrefix(tail, " ") &&
				(strings.HasPrefix(tail[1:], "in") || strings.HasPrefix(tail[1:], "use")) {
				c.ctx.Warn(cm, "the proper format is `Deprecated: <text>`")
				continue
			}
			if strings.HasPrefix(tail, ": ") {
				if i != 0 {
					c.ctx.Warn(cm, "`Deprecated: ` notices should be in a dedicated paragraph, separated from the rest")
				}
			}
			continue
		}
		if strings.HasPrefix(tail, ": ") && hasNotSpace(tail[2:]) {
			c.ctx.Warn(cm, "use `Deprecated: ` (note the casing) instead of `%s`", word+": ")
		}
	}
}

