// splitWord returns the leading run of the ASCII letters and the rest.
func splitWord(s string) (word, rest string) {
	i := 0
	for i < len(s) && isASCIILetter(s[i]) {
		i++
	}
	return s[:i], s[i:]
}

func isASCIILetter(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

// isDeprecatedTypo reports whether the word looks like the `deprecated` word
// with a single character deleted.
