{"command": "cat > checkers_util.go <<'EOF'
package main

import (
	"bytes"
	"go/ast"
	"go/token"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

// nodeSource returns the source code fragment of the given node.
func (ctx *Context) nodeSource(n ast.Node) string {
	if ctx.Pkg == nil || ctx.Pkg.Src == nil {
		return ""
	}
	f := ctx.fileOf(n.Pos())
	if f == nil {
		return ""
	}
	src, ok := ctx.Pkg.Src[f]
	if !ok {
		return ""
	}
	s := f.Offset(n.Pos())
	e := f.Offset(n.End())
	if s < 0 || e > len(src) || s > e {
		return ""
	}
	return string(src[s:e])
}

func (ctx *Context) fileOf(pos token.Pos) *token.File {
	if ctx.Pkg == nil || ctx.Pkg.FSet == nil {
		return nil
	}
	return ctx.Pkg.FSet.File(pos)
}

// render returns a printable representation of the given node.
func (ctx *Context) render(n ast.Node) string {
	return ctx.nodeSource(n)
}

// renderSuggest returns the suggested code for the given node.
func (ctx *Context) renderSuggest(n ast.Node) string {
	return ctx.nodeSource(n)
}

// isStringLit reports whether the expression is a string literal.
func isStringLit(e ast.Expr) bool {
	lit, ok := e.(*ast.BasicLit)
	if !ok {
		return false
	}
	return lit.Kind == token.STRING
}

// intValue returns the integer value of the literal expression or false.
func intValue(e ast.Expr) (int64, bool) {
	lit, ok := e.(*ast.BasicLit)
	if !ok {
		return 0, false
	}
	if lit.Kind != token.INT {
		return 0, false
	}
	v, err := strconv.ParseInt(strings.TrimPrefix(lit.Value, "0o"), 0, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

// identName returns the name of the identifier expression or an empty string.
func identName(e ast.Expr) string {
	id, ok := e.(*ast.Ident)
	if !ok {
		return ""
	}
	return id.Name
}

// unparen returns the expression without the surrounding parentheses.
func unparen(e ast.Expr) ast.Expr {
	for {
		p, ok := e.(*ast.ParenExpr)
		if !ok {
			return e
		}
		e = p.X
	}
}

// isTestFunc reports whether the function is a test or a benchmark function.
func isTestFunc(fn *ast.FuncDecl) bool {
	if !strings.HasPrefix(fn.Name.Name, "Test") &&
		!strings.HasPrefix(fn.Name.Name, "Benchmark") &&
		!strings.HasPrefix(fn.Name.Name, "Example") {
		return false
	}
	return true
}

// isGenerated reports whether the file looks like a generated one.
func isGenerated(f *ast.File) bool {
	for _, cm := range f.Comments {
		for _, c := range cm.List {
			text := strings.TrimPrefix(c.Text, "//")
			text = strings.TrimSpace(text)
			lower := strings.ToLower(text)
			if strings.HasPrefix(lower, "code generated") ||
				strings.Contains(lower, "do not edit") ||
				strings.HasPrefix(lower, "generated by") {
				return true
			}
		}
	}
	return false
}

// utf8Runes returns the number of runes in the string.
func utf8Runes(s string) int {
	n := 0
	for len(s) > 0 {
		_, sz := utf8.DecodeRuneInString(s)
		s = s[sz:]
		n++
	}
	return n
}

// shortenString truncates the string in the middle to fit the given length.
func shortenString(s string, max int) string {
	if utf8Runes(s) <= max {
		return s
	}
	head := max / 2
	tail := max - head
	b := bytes.NewBuffer(nil)
	runes := []rune(s)
	b.WriteString(string(runes[:head]))
	b.WriteString("<...>")
	b.WriteString(string(runes[len(runes)-tail:]))
	return b.String()
}

// isCapitalized reports whether the name starts with an upper case letter.
func isCapitalized(name string) bool {
	if name == "" {
		return false
	}
	r, _ := utf8.DecodeRuneInString(name)
	return unicode.IsUpper(r)
}
EOF
gofmt -w checkers_util.go && echo ok"}

