// stringsCompare detects strings.Compare calls that can be replaced.
type stringsCompare struct {
	checkerBase
}

func newStringsCompare(c *Context) checker { return &stringsCompare{checkerBase{c}} }

func (c *stringsCompare) Visit(n ast.Node) {
