	case token.EQL:
		c.ctx.WarnSuggest(bin, c.ctx.render(bin.X)+" == 0",
			"consider replacing with strings.Equal(%s, %s)", c.ctx.render(call.Args[0]), c.ctx.render(call.Args[1]))
	}
