// equalFold detects case-insensitive comparisons.
type equalFold struct {
	checkerBase
}

func newEqualFold(c *Context) checker { return &equalFold{checkerBase{c}} }

func (c *equalFold) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok || bin.Op != token.EQL && bin.Op != token.NEQ {
		return
	}
	call1, ok := unparen(bin.X).(*ast.CallExpr)
	if !ok || len(call1.Args) != 1 {
		return
	}
	call2, ok := unparen(bin.Y).(*ast.CallExpr)
	if !ok || len(call2.Args) != 1 {
		return
	}
	fn1, fn2 := identName(call1.Fun), identName(call2.Fun)
	if fn1 != fn2 {
		return
	}
	switch fn1 {
	case "ToLower", "ToUpper", "ToLowerSpecial", "ToUpperSpecial":
	default:
		return
	}
	expr := "strings.EqualFold(" + c.ctx.render(call1.Args[0]) + ", " + c.ctx.render(call2.Args[0]) + ")"
	if bin.Op == token.NEQ {
		expr = "!" + expr
	}
	c.ctx.WarnSuggest(bin, expr, "consider replacing with %s", expr)
}

// stringXbytes detects string/bytes conversions that can be simplified.
type stringXbytes struct {
	checkerBase
}

func newStringXbytes(c *Context) checker { return &stringXbytes{checkerBase{c}} }

func (c *stringXbytes) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	name := c.ctx.callName(call)
	suggest := ""
	switch {
	case name == "bytes.Equal" && len(call.Args) == 2:
		suggest = c.ctx.render(call.Args[0]) + " == " + c.ctx.render(call.Args[1])
	case name == "bytes.Compare" && len(call.Args) == 2:
		suggest = "strings.Compare(" + c.ctx.render(call.Args[0]) + ", " + c.ctx.render(call.Args[1]) + ")"
	default:
		return
	}
	c.ctx.WarnSuggest(call, suggest, "suggestion: %s", suggest)
}

// sprintfQuotedString detects quoted strings in format strings.
type sprintfQuotedString struct {
	checkerBase
}

func newSprintfQuotedString(c *Context) checker { return &sprintfQuotedString{checkerBase{c}} }

func (c *sprintfQuotedString) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	name := c.ctx.callName(call)
	if name != "fmt.Sprintf" && name != "fmt.Sprintf" {
		return
	}
	if len(call.Args) < 2 {
		return
	}
	lit, ok := unparen(call.Args[0]).(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return
	}
	if !strings.Contains(lit.Value, `"%s"`) {
		return
	}
	c.ctx.WarnSuggest(call, strings.Replace(lit.Value, `"%s"`, "%q", 1),
		"use %%q instead of \"%s\" for quoted strings", "%s")
}

// filepathJoin detects filepath.Join calls with path separators in the args.
type filepathJoin struct {
	checkerBase
}

func newFilepathJoin(c *Context) checker { return &filepathJoin{checkerBase{c}} }

func (c *filepathJoin) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || c.ctx.callName(call) != "filepath.Join" {
		return
	}
	for _, arg := range call.Args {
		lit, ok := unparen(arg).(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			continue
		}
		v, err := strconv.Unquote(lit.Value)
		if err != nil {
			continue
		}
		if strings.ContainsRune(v, '/') || strings.ContainsRune(v, '\\') {
			c.ctx.Warn(arg, "%q contains a path separator", v)
		}
	}
}

// badLock detects suspicious mutex lock/unlock operations.
type badLock struct {
	checkerBase
}

func newBadLock(c *Context) checker { return &badLock{checkerBase{c}} }

func (c *badLock) Visit(n ast.Node) {
	stmt, ok := n.(ast.Stmt)
	if !ok {
		return
	}
	call, ok := unparen(stmtExpr(stmt)).(*ast.CallExpr)
	if !ok || len(call.Args) != 0 {
		return
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "Lock" {
		return
	}
	next, ok := c.ctx.nextStmt(n).(*ast.ExprStmt)
	if !ok {
		return
	}
	nextCall, ok := next.X.(*ast.CallExpr)
	if !ok {
		return
	}
	nextSel, ok := nextCall.Fun.(*ast.SelectorExpr)
	if !ok || nextSel.Sel.Name != "Unlock" {
		return
	}
	if c.ctx.render(sel.X) != c.ctx.render(nextSel.X) {
		return
	}
	c.ctx.Warn(nextCall, "defer is missing, mutex is unlocked immediately")
}

func stmtExpr(s ast.Stmt) ast.Expr {
	if e, ok := s.(*ast.ExprStmt); ok {
		return e.X
	}
	return nil
}

// hexLiteral detects hex literals that can be written in a shorter way.
type hexLiteral struct {
	checkerBase
}

func newHexLiteral(c *Context) checker { return &hexLiteral{checkerBase{c}} }
