// unslice detects slice expressions that can be simplified to the sliced
// expression itself.
type unslice struct {
	checkerBase
}

func newUnslice(c *Context) checker { return &unslice{checkerBase{c}} }

func (c *unslice) Visit(n ast.Node) {
	e, ok := n.(*ast.SliceExpr)
	if !ok || e.Low != nil || e.High != nil || e.Slice3 {
		return
	}
	// The slice expression should not be applied to an array.
	t := c.ctx.TypeOf(e.X)
	if t == nil {
		return
	}
	switch t.Underlying().(type) {
	case *types.Slice, *types.Map, *types.Pointer:
	default:
		return
	}
	x := c.ctx.render(e.X)
	c.ctx.WarnSuggest(e, x, "could simplify %s[:] to %s", x, x)
}

// assignOp detects assignments that can be simplified by using assignment
// operators.
type assignOp struct {
	checkerBase
}

func newAssignOp(c *Context) checker { return &assignOp{checkerBase{c}} }

var assignOpTokens = map[token.Token]string{
	token.ADD: "+", token.SUB: "-", token.MUL: "*", token.QUO: "/", token.REM: "%",
	token.SHL: "<<", token.SHR: ">>", token.AND: "&", token.OR: "|", token.XOR: "^",
	token.AND_NOT: "&^",
}

func (c *assignOp) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	bin, ok := assign.Rhs[0].(*ast.BinaryExpr)
	if !ok {
		return
	}
	op, ok := assignOpTokens[bin.Op]
	if !ok {
		return
	}
	lhs := c.ctx.render(assign.Lhs[0])
	var other ast.Expr
	switch {
	case exprEqual(bin.X, assign.Lhs[0]):
		other = bin.Y
	case exprEqual(bin.Y, assign.Lhs[0]):
		other = bin.X
	default:
		return
	}
	// x = x + 1 is a good candidate for the increment statement.
	if bin.Op == token.ADD || bin.Op == token.SUB {
		if lit, ok := unparen(other).(*ast.BasicLit); ok && lit.Kind == token.INT {
			if v, err := strconv.ParseInt(strings.TrimPrefix(lit.Value, "0o"), 0, 64); err == nil && v == 1 {
				opStr := "++"
				if bin.Op == token.SUB {
					opStr = "--"
				}
				c.ctx.WarnSuggest(assign, lhs+opStr,
					"replace `%s` with `%s%s`", c.ctx.render(assign), lhs, opStr)
				return
			}
		}
	}
	c.ctx.WarnSuggest(assign, lhs+" "+op+"= "+c.ctx.render(other),
		"replace `%s` with `%s %s= %s`", c.ctx.render(assign), lhs, op, c.ctx.render(other))
}

// exprEqual reports whether the two expressions are the same identifier-like
// expressions.
func exprEqual(a, b ast.Expr) bool {
	return a != nil && b != nil && cExprText(a) == cExprText(b)
}

func cExprText(e ast.Expr) string {
	return ""
}

// sloppyLen detects usage of `len` when result is obvious.
type sloppyLen struct {
	checkerBase
}

func newSloppyLen(c *Context) checker { return &sloppyLen{checkerBase{c}} }

func (c *sloppyLen) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok {
		return
	}
	call := lenCall(bin.X)
	if call == nil {
		call = lenCall(bin.Y)
		if call == nil {
			return
		}
		// 0 > len(x) and other reversed forms.
		switch bin.Op {
		case token.LSS: // 0 < len(x)
			c.ctx.WarnSuggest(bin, c.ctx.render(call), "%s >= 0 is always true", c.ctx.render(call))
		case token.GEQ: // 0 >= len(x)
			c.ctx.WarnSuggest(bin, c.ctx.render(call), "%s <= 0 can be %s == 0", c.ctx.render(call), c.ctx.render(call))
		case token.LEQ: // 0 <= len(x)
			return
		case token.GTR: // 0 > len(x)
			c.ctx.WarnSuggest(bin, c.ctx.render(call), "%s < 0 is always false", c.ctx.render(call))
		}
		return
	}
	arg := c.ctx.render(call)
	switch bin.Op {
	case token.LSS: // len(x) < 0
		c.ctx.WarnSuggest(bin, arg+" == 0", "%s < 0 is always false", arg)
	case token.GEQ: // len(x) >= 0
		c.ctx.WarnSuggest(bin, arg+" != 0", "%s >= 0 is always true", arg)
	case token.LEQ: // len(x) <= 0
		c.ctx.WarnSuggest(bin, arg+" == 0", "%s <= 0 can be %s == 0", arg, arg)
	}
}

// lenCall returns the `len(x)` call expression or nil.
func lenCall(e ast.Expr) *ast.CallExpr {
	call, ok := unparen(e).(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return nil
	}
	if identName(call.Fun) != "len" {
		return nil
	}
	return call
}

// emptyStringTest detects `len(x) == 0` style tests.
type emptyStringTest struct {
	checkerBase
}

func newEmptyStringTest(c *Context) checker { return &emptyStringTest{checkerBase{c}} }

func (c *emptyStringTest) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok {
		return
	}
	call := lenCall(bin.X)
	other := bin.Y
	if call == nil {
		call = lenCall(bin.Y)
		other = bin.X
	}
	if call == nil {
		return
	}
	t := c.ctx.TypeOf(call.Args[0])
	if t == nil || t.Underlying() != types.Typ[types.String] {
		return
	}
	lit, ok := unparen(other).(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING || lit.Value != `""` {
		return
	}
	arg := c.ctx.render(call.Args[0])
	repl := arg
	switch bin.Op {
	case token.EQL, token.LEQ:
		repl = arg + ` == ""`
	case token.GTR, token.GEQ:
		repl = arg + ` != ""`
	default:
		return
	}
	c.ctx.WarnSuggest(bin, repl, "replace `%s` with `%s`", c.ctx.render(bin), repl)
}

// singleCaseSwitch detects switch statements that can be replaced with if.
type singleCaseSwitch struct {
	checkerBase
}

func newSingleCaseSwitch(c *Context) checker { return &singleCaseSwitch{checkerBase{c}} }

func (c *singleCaseSwitch) Visit(n ast.Node) {
	sw, ok := n.(*ast.SwitchStmt)
	if !ok || sw.Body == nil {
		return
	}
	cases := 0
	hasDefault := false
	for _, stmt := range sw.Body.List {
		clause, ok := stmt.(*ast.CaseClause)
		if !ok {
			continue
		}
		if clause.List == nil {
			hasDefault = true
			continue
		}
		cases++
	}
	if cases != 1 || hasDefault {
		return
	}
	c.ctx.Warn(sw, "should rewrite switch statement to if statement")
}

// switchTrue detects `switch true {}` statements.
type switchTrue struct {
	checkerBase
}

func newSwitchTrue(c *Context) checker { return &switchTrue{checkerBase{c}} }

func (c *switchTrue) Visit(n ast.Node) {
	sw, ok := n.(*ast.SwitchStmt)
	if !ok || sw.Body == nil || sw.Tag == nil {
		return
	}
	if identName(unparen(sw.Tag)) != "true" {
		return
	}
	old := c.ctx.render(sw)
	newTxt := strings.TrimSuffix(strings.TrimPrefix(old, "switch "), "true {")
	c.ctx.WarnSuggest(sw, "switch "+newTxt, "replace '%s' with '%s'", old, "switch "+newTxt)
}

// ifElseChain detects if-else chains that can be replaced with a switch.
type ifElseChain struct {
	checkerBase
}

func newIfElseChain(c *Context) checker { return &ifElseChain{checkerBase{c}} }

func (c *ifElseChain) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok {
		return
	}
	// Only the outermost if is reported.
	if isElseIf(ife) {
		return
	}
	count := 0
	for e := ife.Else; e != nil; {
		elseIf, ok := e.(*ast.IfStmt)
		if !ok {
			break
		}
		count++
		e = elseIf.Else
	}
	if count < c.ctx.ParamInt("minThreshold", 2) {
		return
	}
	c.ctx.Warn(ife, "rewrite if-else to switch statement")
}

func isElseIf(ife *ast.IfStmt) bool {
	return ife.Else != nil
}

// elseif detects `else { if ... }` blocks.
type elseif struct {
	checkerBase
	skipBalanced bool
}

func newElseif(c *Context) checker {
	return &elseif{checkerBase: checkerBase{c}, skipBalanced: c.ParamBool("skipBalanced", true)}
}

func (c *elseif) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok || ife.Else == nil {
		return
	}
	block, ok := ife.Else.(*ast.BlockStmt)
	if !ok || len(block.List) != 1 {
		return
	}
	inner, ok := block.List[0].(*ast.IfStmt)
	if !ok {
		return
	}
	if c.skipBalanced && inner.Else != nil {
		return
	}
	c.ctx.Warn(ife.Else, "can replace 'else {if cond {}}' with 'else if cond {}'")
}

// defaultCaseOrder detects switch statements with the default case in the
// middle.
type defaultCaseOrder struct {
	checkerBase
}

func newDefaultCaseOrder(c *Context) checker { return &defaultCaseOrder{checkerBase{c}} }

func (c *defaultCaseOrder) Visit(n ast.Node) {
	var body *ast.BlockStmt
	switch n := n.(type) {
	case *ast.SwitchStmt:
		body = n.Body
	case *ast.TypeSwitchStmt:
		body = n.Body
	}
	if body == nil {
		return
	}
	defaultIdx := -1
	caseCount := 0
	for i, stmt := range body.List {
		clause, ok := stmt.(*ast.CaseClause)
		if !ok {
			continue
		}
		if clause.List == nil {
			defaultIdx = i
		} else {
			caseCount++
		}
	}
	if defaultIdx <= 0 || defaultIdx == len(body.List)-1 {
		return
	}
	c.ctx.Warn(body.List[defaultIdx], "consider to make `default` case as first or as last case")
}

// dupBranchBody detects if statements with the same then and else bodies.
type dupBranchBody struct {
	checkerBase
}

func newDupBranchBody(c *Context) checker { return &dupBranchBody{checkerBase{c}} }

func (c *dupBranchBody) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok || ife.Else == nil {
		return
	}
	thenTxt := c.ctx.render(ife.Body)
	var elseTxt string
	switch e := ife.Else.(type) {
	case *ast.BlockStmt:
		elseTxt = c.ctx.render(e)
	case *ast.IfStmt:
		elseTxt = c.ctx.render(e)
	}
	if thenTxt == "" || thenTxt != elseTxt {
		return
	}
	c.ctx.Warn(ife, "both branches in if statement have same body")
}

// dupCase detects duplicated case clauses.
type dupCase struct {
	checkerBase
}

func newDupCase(c *Context) checker { return &dupCase{checkerBase{c}} }

func (c *dupCase) Visit(n ast.Node) {
	var body *ast.BlockStmt
	switch n := n.(type) {
	case *ast.SwitchStmt:
		body = n.Body
	case *ast.TypeSwitchStmt:
		body = n.Body
	}
	if body == nil {
		return
	}
	seen := map[string]bool{}
	for _, stmt := range body.List {
		clause, ok := stmt.(*ast.CaseClause)
		if !ok {
			continue
		}
		for _, e := range clause.List {
			txt := c.ctx.render(e)
			if seen[txt] {
				c.ctx.Warn(clause, "'case %s' is duplicated", txt)
				continue
			}
			seen[txt] = true
		}
	}
}

// offBy1 detects index expressions that always panic.
type offBy1 struct {
	checkerBase
}

func newOffBy1(c *Context) checker { return &offBy1{checkerBase{c}} }

func (c *offBy1) Visit(n ast.Node) {
	idx, ok := n.(*ast.IndexExpr)
	if !ok {
		return
	}
	call, ok := unparen(idx.Index).(*ast.CallExpr)
	if !ok || identName(call.Fun) != "len" || len(call.Args) != 1 {
		return
	}
	if !exprTextEqual(idx.X, call.Args[0]) {
		return
	}
	c.ctx.WarnSuggest(idx, c.ctx.render(idx.X)+"[len("+c.ctx.render(idx.X)+")-1]",
		"index expr always panics; maybe you wanted %s[len(%s)-1]?",
		c.ctx.render(idx.X), c.ctx.render(idx.X))
}

func exprTextEqual(a, b ast.Expr) bool {
	return a != nil && b != nil && a.End()-a.Pos() == b.End()-b.Pos()
}

// appendAssign detects suspicious append result assignments.
type appendAssign struct {
	checkerBase
}

func newAppendAssign(c *Context) checker { return &appendAssign{checkerBase{c}} }

func (c *appendAssign) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	call, ok := assign.Rhs[0].(*ast.CallExpr)
	if !ok || identName(call.Fun) != "append" || len(call.Args) == 0 {
		return
	}
	lhs := c.ctx.render(assign.Lhs[0])
	rhs := c.ctx.render(call.Args[0])
	if lhs == rhs {
		return
	}
	// A conversion of the appended slice is allowed.
	if conv, ok := call.Args[0].(*ast.CallExpr); ok && len(conv.Args) == 1 {
		if inner, ok := conv.Args[0].(*ast.Ident); ok && inner.Name == lhs {
			return
		}
	}
	c.ctx.Warn(assign, "append result not assigned to the same slice")
}

// appendCombine detects append chains that can be combined.
type appendCombine struct {
	checkerBase
}

func newAppendCombine(c *Context) checker { return &appendCombine{checkerBase{c}} }

func (c *appendCombine) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	call, ok := assign.Rhs[0].(*ast.CallExpr)
	if !ok || identName(call.Fun) != "append" || len(call.Args) == 0 {
		return
	}
	varName := c.ctx.render(assign.Lhs[0])
	if c.ctx.render(call.Args[0]) != varName {
		return
	}
	next, ok := c.ctx.nextStmt(n).(*ast.AssignStmt)
	if !ok || len(next.Lhs) != 1 || len(next.Rhs) != 1 {
		return
	}
	nextCall, ok := next.Rhs[0].(*ast.CallExpr)
	if !ok || identName(nextCall.Fun) != "append" || len(nextCall.Args) == 0 {
		return
	}
	if c.ctx.render(next.Lhs[0]) != varName || c.ctx.render(nextCall.Args[0]) != varName {
		return
	}
	c.ctx.Warn(assign, "can combine chain of %d appends into one", 2)
}

// deferInLoop detects defers inside loops.
type deferInLoop struct {
	checkerBase
}

func newDeferInLoop(c *Context) checker { return &deferInLoop{checkerBase{c}} }

func (c *deferInLoop) Visit(n ast.Node) {
	stmt, ok := n.(ast.Stmt)
	if !ok {
		return
	}
	var ds *ast.DeferStmt
	switch s := stmt.(type) {
	case *ast.DeferStmt:
		ds = s
	case *ast.LabeledStmt:
		if d, ok := s.Stmt.(*ast.DeferStmt); ok {
			ds = d
		}
	}
	if ds == nil {
		return
	}
	if !c.ctx.insideLoop(ds) {
		return
	}
	c.ctx.Warn(ds, "Possible resource leak, 'defer' is called in the 'for' loop")
}

// unlabelStmt detects redundant labels.
type unlabelStmt struct {
	checkerBase
}

func newUnlabelStmt(c *Context) checker { return &unlabelStmt{checkerBase{c}} }

func (c *unlabelStmt) Visit(n ast.Node) {
	lbl, ok := n.(*ast.LabeledStmt)
	if !ok {
		return
	}
	// The label is redundant if it is attached to a statement that is not
	// referenced by any break/continue.
	if !c.ctx.labelUsed(lbl.Label.Name) {
		c.ctx.Warn(lbl, "label %s is redundant", lbl.Label.Name)
	}
}

// dupArg detects function calls with duplicated arguments.
type dupArg struct {
	checkerBase
}

func newDupArg(c *Context) checker { return &dupArg{checkerBase{c}} }

func (c *dupArg) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || len(call.Args) == 0 {
		return
	}
	if !c.ctx.isDupArgFunc(call) {
		return
	}
	for i := 0; i < len(call.Args)-1; i++ {
		for j := i + 1; j < len(call.Args); j++ {
			if c.ctx.render(call.Args[i]) == c.ctx.render(call.Args[j]) {
				c.ctx.Warn(call, "suspicious duplicated args in %s", c.ctx.render(call))
				return
			}
		}
	}
}

// argOrder detects suspicious arguments order.
type argOrder struct {
	checkerBase
}

func newArgOrder(c *Context) checker { return &argOrder{checkerBase{c}} }

func (c *argOrder) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || len(call.Args) != 2 {
		return
	}
	if !c.ctx.isArgOrderFunc(call) {
		return
	}
	lit, ok := unparen(call.Args[0]).(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return
	}
	if isStringLit(unparen(call.Args[1])) {
		return
	}
	first := c.ctx.render(call.Args[0])
	second := c.ctx.render(call.Args[1])
	c.ctx.Warn(call, "`%s` and %s arguments order looks reversed", first, second)
}

// badCall detects suspicious function calls.
type badCall struct {
	checkerBase
}

func newBadCall(c *Context) checker { return &badCall{checkerBase{c}} }

func (c *badCall) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	name := c.ctx.callName(call)
	switch name {
	case "strings.Join", "bytes.Join":
		if len(call.Args) == 1 {
			c.ctx.Warn(call, "suspicious %s on 1 argument", identName(call.Fun))
		}
	case "strings.Replace", "bytes.Replace":
		if len(call.Args) == 4 {
			if v, ok := intValue(unparen(call.Args[3])); ok && v == 0 {
				c.ctx.Warn(call, "suspicious arg 0, probably meant -1")
			}
		}
	}
}

// badCond detects suspicious condition expressions.
type badCond struct {
	checkerBase
}

func newBadCond(c *Context) checker { return &badCond{checkerBase{c}} }

func (c *badCond) Visit(n ast.Node) {
	bin, ok := unparen(n).(ast.Expr)
	if !ok {
		return
	}
	b, ok := bin.(*ast.BinaryExpr)
	if !ok || b.Op != token.LAND && b.Op != token.LOR {
		return
	}
	lhs, ok := unparen(b.X).(*ast.BinaryExpr)
	if !ok {
		return
	}
	rhs, ok := unparen(b.Y).(*ast.BinaryExpr)
	if !ok {
		return
	}
	if c.ctx.render(lhs.X) != c.ctx.render(rhs.X) && c.ctx.render(lhs.X) != c.ctx.render(rhs.Y) {
		return
	}
	c.ctx.Warn(b, "`%s` condition is suspicious", c.ctx.render(b))
}

// captLocal detects capitalized local variable names.
type captLocal struct {
	checkerBase
	paramsOnly bool
}

func newCaptLocal(c *Context) checker {
	return &captLocal{checkerBase: checkerBase{c}, paramsOnly: c.ParamBool("paramsOnly", true)}
}

func (c *captLocal) Visit(n ast.Node) {
	switch n := n.(type) {
	case *ast.FuncDecl:
		if n.Type.Results != nil {
			c.checkFields(n.Type.Results)
		}
		if n.Type.Params != nil {
			c.checkFields(n.Type.Params)
		}
	case *ast.AssignStmt:
		if c.paramsOnly {
			return
		}
		for _, e := range n.Lhs {
			id, ok := e.(*ast.Ident)
			if !ok {
				continue
			}
			c.checkIdent(id)
		}
	case *ast.GenDecl:
		if c.paramsOnly {
			return
		}
		for _, spec := range n.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok {
				continue
			}
			for _, id := range vs.Names {
				c.checkIdent(id)
			}
		}
	}
}

func (c *captLocal) checkFields(fl *ast.FieldList) {
	for _, field := range fl.List {
		for _, id := range field.Names {
			c.checkIdent(id)
		}
	}
}

func (c *captLocal) checkIdent(id *ast.Ident) {
	if !isCapitalized(id.Name) {
		return
	}
	// Exported names are fine.
	if id.Obj != nil && id.Obj.Kind == ast.Pkg {
		return
	}
	c.ctx.Warn(id, "`%s' should not be capitalized", id.Name)
}

// exitAfterDefer detects functions that exit after a defer statement.
type exitAfterDefer struct {
	checkerBase
}

func newExitAfterDefer(c *Context) checker { return &exitAfterDefer{checkerBase{c}} }

func (c *exitAfterDefer) Visit(n ast.Node) {
	block, ok := n.(*ast.BlockStmt)
	if !ok {
		return
	}
	for _, stmt := range block.List {
		switch s := stmt.(type) {
		case *ast.ExprStmt:
			call, ok := s.X.(*ast.CallExpr)
			if !ok {
				continue
			}
			if !c.ctx.isExitCall(call) {
				continue
			}
			name := c.ctx.callName(call)
			for _, d := range c.ctx.defersBefore(block, stmt) {
				c.ctx.Warn(call, "%s will exit, and `defer %s` will not run", name, c.ctx.renderDefer(d))
			}
		}
	}
}

// wrapperFunc detects functions that have a wrapper alternative.
type wrapperFunc struct {
	checkerBase
}

func newWrapperFunc(c *Context) checker { return &wrapperFunc{checkerBase{c}} }

func (c *wrapperFunc) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	repl, wrapper := c.ctx.wrapperFor(call)
	if wrapper == "" {
		return
	}
	c.ctx.WarnSuggest(call, repl, "use %s method in `%s`", wrapper, c.ctx.render(call))
}

// redundantSprint detects redundant fmt.Sprint calls.
type redundantSprint struct {
	checkerBase
}

func newRedundantSprint(c *Context) checker { return &redundantSprint{checkerBase{c}} }

func (c *redundantSprint) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	name := c.ctx.callName(call)
	if name != "fmt.Sprintf" && name != "fmt.Sprint" {
		return
	}
	if len(call.Args) != 1 {
		return
	}
	arg := call.Args[0]
	t := c.ctx.TypeOf(arg)
	if t == nil {
		return
	}
	// fmt.Sprintf("%s", s) where s is a string.
	if name == "fmt.Sprintf" {
		lit, ok := unparen(arg).(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING || lit.Value != `"%s"` {
			return
		}
	}
	if isStringer(t) {
		c.ctx.Warn(call, "use %s.String() instead", c.ctx.render(arg))
		return
	}
	if t.Underlying() == types.Typ[types.String] && name == "fmt.Sprint" {
		c.ctx.Warn(call, "%s is already string", c.ctx.render(arg))
	}
}

func isStringer(t types.Type) bool {
	// Look up the String() string method.
	ms := types.NewMethodSet(t)
	sel := ms.Lookup(nil, "String")
	if sel == nil {
		return false
	}
	sig, ok := sel.Type().(*types.Signature)
	if !ok {
		return false
	}
	if sig.Params().Len() != 0 {
		return false
	}
	res := sig.Results()
	if res.Len() != 1 || res.At(0).Type().Underlying() != types.Typ[types.String] {
		return false
	}
	return true
}

// dynamicFmtString detects dynamic format strings.
type dynamicFmtString struct {
	checkerBase
}

func newDynamicFmtString(c *Context) checker { return &dynamicFmtString{checkerBase{c}} }

func (c *dynamicFmtString) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	if c.ctx.callName(call) != "fmt.Errorf" || len(call.Args) != 2 {
		return
	}
	arg := call.Args[0]
	if isStringLit(unparen(arg)) {
		return
	}
	t := c.ctx.TypeOf(arg)
	if t == nil || t.Underlying() != types.Typ[types.String] {
		return
	}
	c.ctx.WarnSuggest(call, "errors.New("+c.ctx.render(arg)+")",
		"use errors.New(%s) or fmt.Errorf(\"%%s\", %s) instead", c.ctx.render(arg), c.ctx.render(arg))
}

// octalLiteral detects old-style octal literals.
type octalLiteral struct {
	checkerBase
}

func newOctalLiteral(c *Context) checker { return &octalLiteral{checkerBase{c}} }

func (c *octalLiteral) Visit(n ast.Node) {
	lit, ok := n.(*ast.BasicLit)
	if !ok || lit.Kind != token.INT {
		return
	}
	if !strings.HasPrefix(lit.Value, "0") || lit.Value == "0" {
		return
	}
	v := lit.Value[1:]
	if v == "" {
		return
	}
	for i := 0; i < len(v); i++ {
		if v[i] < '0' || v[i] > '7' {
			return
		}
	}
	c.ctx.WarnSuggest(lit, "0o"+v, "use new octal literal style, 0o%s", v)
}

// dupSubExpr detects identical LHS and RHS.
type dupSubExpr struct {
	checkerBase
}

func newDupSubExpr(c *Context) checker { return &dupSubExpr{checkerBase{c}} }

func (c *dupSubExpr) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok {
		return
	}
	switch bin.Op {
	case token.EQL, token.NEQ, token.LSS, token.GTR, token.LEQ, token.GEQ,
		token.LAND, token.LOR, token.SUB, token.QUO, token.REM, token.AND,
		token.OR, token.XOR, token.AND_NOT:
	default:
		return
	}
	if c.ctx.render(bin.X) != c.ctx.render(bin.Y) {
		return
	}
	if isConstExpr(bin.X) {
		return
	}
	c.ctx.Warn(bin, "suspicious identical LHS and RHS for `%s` operator", bin.Op.String())
}

func isConstExpr(e ast.Expr) bool {
	switch e.(type) {
	case *ast.BasicLit, *ast.Ident:
		return false
	}
	return false
}

// caseOrder detects erroneous case order inside type switch statements.
type caseOrder struct {
	checkerBase
}

func newCaseOrder(c *Context) checker { return &caseOrder{checkerBase{c}} }

func (c *caseOrder) Visit(n ast.Node) {
	ts, ok := n.(*ast.TypeSwitchStmt)
	if !ok || ts.Body == nil {
		return
	}
	var prev []types.Type
	for _, stmt := range ts.Body.List {
		clause, ok := stmt.(*ast.CaseClause)
		if !ok {
			continue
		}
		var cur []types.Type
		for _, e := range clause.List {
			t := c.ctx.TypeOf(e)
			if t == nil {
				continue
			}
			cur = append(cur, t)
		}
		for _, pt := range prev {
			for _, ct := range cur {
				if types.Implements(ct, pt.Interface()) {
					continue
				}
			}
		}
		// Detect the supertype-before-subtype order.
		for _, pt := range prev {
			if pt == nil {
				continue
			}
			for _, ct := range cur {
				if ct == nil {
					continue
				}
				if isSupertype(pt, ct) {
					c.ctx.Warn(clause, "case %s is unreachable, because %s is a supertype",
						c.ctx.render(clause.List[0]), typeString(pt))
				}
			}
		}
		prev = append(prev, cur...)
	}
}

func isSupertype(a, b types.Type) bool {
	return false
}

func typeString(t types.Type) string {
	if t == nil {
		return ""
	}
	return t.String()
}

// typeSwitchVar detects type switch variables that are not used in all cases.
type typeSwitchVar struct {
	checkerBase
}

func newTypeSwitchVar(c *Context) checker { return &typeSwitchVar{checkerBase{c}} }

func (c *typeSwitchVar) Visit(n ast.Node) {
	ts, ok := n.(*ast.TypeSwitchStmt)
	if !ok || ts.Body == nil {
		return
	}
	assign, ok := ts.Assign.(*ast.ExprStmt)
	if !ok {
		return
	}
	_ = assign
}

// mapKey detects duplicated map keys.
type mapKey struct {
	checkerBase
}

func newMapKey(c *Context) checker { return &mapKey{checkerBase{c}} }

func (c *mapKey) Visit(n ast.Node) {
	lit, ok := n.(*ast.CompositeLit)
	if !ok {
		return
	}
	t := c.ctx.TypeOf(lit)
	if t == nil {
		return
	}
	mt, ok := t.Underlying().(*types.Map)
	if !ok {
		return
	}
	seen := map[string]bool{}
	for _, e := range lit.Elts {
		kv, ok := e.(*ast.KeyValueExpr)
		if !ok {
			continue
		}
		key := c.ctx.render(kv.Key)
		if seen[key] {
			c.ctx.Warn(kv, "duplicate key %s in map literal of type %s", key, mt.Key())
			continue
		}
		seen[key] = true
	}
}

// regexpMust detects regexp.MustCompile calls that can be regexp.MustCompile.
type regexpMust struct {
	checkerBase
}

func newRegexpMust(c *Context) checker { return &regexpMust{checkerBase{c}} }

func (c *regexpMust) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || len(assign.Rhs) != 1 {
		return
	}
	call, ok := assign.Rhs[0].(*ast.CallExpr)
	if !ok {
		return
	}
	name := c.ctx.callName(call)
	if name != "regexp.Compile" && name != "regexp.CompilePOSIX" {
		return
	}
	if len(call.Args) != 1 {
		return
	}
	if !isStringLit(unparen(call.Args[0])) {
		return
	}
	fn := "regexp.MustCompile"
	if name == "regexp.CompilePOSIX" {
		fn = "regexp.MustCompilePOSIX"
	}
	c.ctx.WarnSuggest(assign, c.ctx.render(assign.Lhs[0])+" := "+fn+"("+c.ctx.render(call.Args[0])+")",
		"for const patterns like %s, consider %s", c.ctx.render(call.Args[0]), fn)
}

// sloppyTypeAssert detects type assertions that can be type switches.
type sloppyTypeAssert struct {
	checkerBase
}

func newSloppyTypeAssert(c *Context) checker { return &sloppyTypeAssert{checkerBase{c}} }

func (c *sloppyTypeAssert) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok {
		return
	}
	init, ok := ife.Init.(*ast.AssignStmt)
	if !ok || len(init.Lhs) != 2 || len(init.Rhs) != 1 {
		return
	}
	ta, ok := init.Rhs[0].(*ast.TypeAssertExpr)
	if !ok || ta.Type == nil {
		return
	}
	cond := c.ctx.render(ife.Cond)
	if cond != c.ctx.render(init.Lhs[1]) {
		return
	}
	c.ctx.Warn(ife, "type assert `%%s` can be simplified")
}

// unlambda detects immediately-invoked function literals.
type unlambda struct {
	checkerBase
}

func newUnlambda(c *Context) checker { return &unlambda{checkerBase{c}} }

func (c *unlambda) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok {
		return
	}
	lit, ok := call.Fun.(*ast.FuncLit)
	if !ok {
		return
	}
	if len(call.Args) != 0 {
		return
	}
	if lit.Type.Results != nil && len(lit.Type.Results.List) != 0 {
		return
	}
	c.ctx.Warn(call, "omit the lambda, use %s directly", c.ctx.render(lit))
}

// valSwap detects manual swaps that can use tuple assignment.
type valSwap struct {
	checkerBase
}

func newValSwap(c *Context) checker { return &valSwap{checkerBase{c}} }

func (c *valSwap) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
}

// newDeref detects redundant dereferences of new() results.
type newDeref struct {
	checkerBase
