	checkerBase
	skipRecvDeref bool
}

func newUnderef(c *Context) checker {
	return &underef{checkerBase: checkerBase{c}, skipRecvDeref: c.ParamBool("skipRecvDeref", true)}
}

func (c *underef) Visit(n ast.Node) {
	un, ok := unparen(n).(*ast.StarExpr)
