	if !ok {
		return
	}
	call, ok := unparen(bin.X).(*ast.CallExpr)
	if !ok || c.ctx.callName(call) != "strings.Compare" || len(call.Args) != 2 {
		return
	}
	switch bin.Op {
	case token.EQL:
		c.ctx.WarnSuggest(bin, c.ctx.render(bin.X)+" == 0",
			"consider replacing with strings.Equal(%s, %s)", c.ctx.render(call.Args[0]), c.ctx.render(call.Args[1]))
	}
