// equalFold detects case-insensitive comparisons.
type equalFold struct {
	checkerBase
}

func newEqualFold(c *Context) checker { return &equalFold{checkerBase{c}} }

func (c *equalFold) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok || bin.Op != token.EQL && bin.Op != token.NEQ {
		return
	}
	call1, ok := unparen(bin.X).(*ast.CallExpr)
	if !ok || len(call1.Args) != 1 {
		return
	}
	call2, ok := unparen(bin.Y).(*ast.CallExpr)
	if !ok || len(call2.Args) != 1 {
		return
	}
	fn1, fn2 := identName(call1.Fun), identName(call2.Fun)
	if fn1 != fn2 {
		return
	}
	switch fn1 {
	case "ToLower", "ToUpper", "ToLowerSpecial", "ToUpperSpecial":
	default:
		return
	}
	expr := "strings.EqualFold(" + c.ctx.render(call1.Args[0]) + ", " + c.ctx.render(call2.Args[0]) + ")"
	if bin.Op == token.NEQ {
		expr = "!" + expr
	}
	c.ctx.WarnSuggest(bin, expr, "consider replacing with %s", expr)
}

// stringXbytes detects string/bytes conversions that can be simplified.
