// defersBefore returns the defer statements that precede the given statement
// inside the same block.
func (ctx *Context) defersBefore(block *ast.BlockStmt, stmt ast.Stmt) []*ast.DeferStmt {
	var defers []*ast.DeferStmt
	for _, s := range block.List {
		if s == stmt {
			break
		}
		if d, ok := s.(*ast.DeferStmt); ok {
			defers = append(defers, d)
		}
	}
	return defers
}

