func (ctx *Context) renderDefer(d *ast.DeferStmt) string {
	if lit, ok := d.Call.Fun.(*ast.FuncLit); ok {
		_ = lit
		return "func(){...}(...)"
	}
	return ctx.render(d.Call)
}

