// nextStmt returns the statement that follows the given one in its block.
func (ctx *Context) nextStmt(n ast.Node) ast.Stmt {
	if ctx.Pkg == nil {
		return nil
	}
	block, ok := ctx.Pkg.blockOf[n]
	if !ok {
		return nil
	}
	for i, s := range block.List {
		if s == n && i+1 < len(block.List) {
			return block.List[i+1]
		}
	}
	return nil
}

