func analyzePkg(pkg *Package) {
	pkg.loopNodes = map[ast.Node]bool{}
	pkg.labelUsed = map[string]bool{}
	pkg.blockOf = map[ast.Stmt]*ast.BlockStmt{}
	pkg.labelDecl = map[string]*ast.LabeledStmt{}
	pkg.elseIfNodes = map[ast.Node]bool{}
	pkg.labelRedundant = map[ast.Node]bool{}
	for _, f := range pkg.Syntax {
		var walk func(n ast.Node, inLoop bool, block *ast.BlockStmt)
		walk = func(n ast.Node, inLoop bool, block *ast.BlockStmt) {
			ast.Inspect(n, func(n ast.Node) bool {
				if n == nil {
					return false
				}
				if inLoop {
					pkg.loopNodes[n] = true
				}
				switch n := n.(type) {
				case *ast.ForStmt:
					if n.Body != nil {
						walk(n.Body, true, n.Body)
						return false
					}
				case *ast.RangeStmt:
					if n.Body != nil {
						walk(n.Body, true, n.Body)
						return false
					}
				case *ast.IfStmt:
					if block, ok := n.Else.(*ast.BlockStmt); ok {
						if len(block.List) == 1 {
							if _, ok := block.List[0].(*ast.IfStmt); ok {
								pkg.elseIfNodes[block.List[0]] = true
							}
						}
					}
				case *ast.BlockStmt:
					for _, s := range n.List {
						pkg.blockOf[s] = n
					}
				case *ast.BranchStmt:
					if n.Label != nil {
						pkg.labelUsed[n.Label.Name] = true
					}
				case *ast.LabeledStmt:
					if _, ok := pkg.labelDecl[n.Label.Name]; !ok {
						pkg.labelDecl[n.Label.Name] = n
					}
				}
				return true
			})
		}
		walk(f, false, nil)
		// A label is redundant when it is only used by the branches that are
		// located directly inside the labeled statement.
		for name, lbl := range pkg.labelDecl {
			used := false
			ast.Inspect(lbl.Stmt, func(n ast.Node) bool {
				if br, ok := n.(*ast.BranchStmt); ok && br.Label != nil && br.Label.Name == name {
					if block, ok := pkg.blockOf[br]; ok && lbl.Stmt == block {
						return true
					}
					used = true
				}
				return true
			})
			if !used {
				pkg.labelRedundant[lbl] = true
			}
		}
		// Collect the comments that are located inside function bodies.
		for _, decl := range f.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok || fd.Body == nil {
				continue
			}
			start, end := fd.Body.Pos(), fd.Body.End()
			for _, cg := range f.Comments {
				if cg.Pos() > start && cg.End() < end {
					pkg.funcComments = append(pkg.funcComments, cg)
				}
			}
		}
	}
}
'''
