		fl = n.Type.Params
		c.checkFieldList(n, fl, "func")
		if n.Type.Results != nil {
			c.checkResultList(n, n.Type.Results)
		}
	case *ast.FuncLit:
		fl = n.Type.Params
		c.checkFieldList(n, fl, "func")
		if n.Type.Results != nil {
			c.checkResultList(n, n.Type.Results)
		}
	}
	_ = fl
}

func (c *paramTypeCombine) checkFieldList(n ast.Node, fl *ast.FieldList, prefix string) {
	if fl == nil || len(fl.List) < 2 {
		return
	}
	// Find the adjacent fields of the same type.
	var newFields []string
	combined := false
	for i := 0; i < len(fl.List); i++ {
		j := i
		names := []string{}
		for j < len(fl.List) && c.ctx.exprText(fl.List[j].Type) == c.ctx.exprText(fl.List[i].Type) {
			for _, id := range fl.List[j].Names {
				names = append(names, id.Name)
			}
			j++
		}
		if j-i > 1 {
			combined = true
		}
		typ := c.ctx.exprText(fl.List[i].Type)
		if len(names) > 1 {
			newFields = append(newFields, strings.Join(names, ", ")+" "+typ)
		} else {
			newFields = append(newFields, names[0]+" "+typ)
		}
		i = j - 1
	}
	if !combined {
		return
	}
	c.ctx.Warn(n.Type.Params, "%s(%s) could be replaced with %s(%s)",
		prefix, strings.Join(newFields, ", "), prefix, strings.Join(newFields, ", "))
}

func (c *paramTypeCombine) checkResultList(n ast.Node, fl *ast.FieldList) {
	_ = fl
}

// builtinShadow detects shadowing of the predeclared identifiers.
type builtinShadow struct {
	checkerBase
}

func newBuiltinShadow(c *Context) checker { return &builtinShadow{checkerBase{c}} }

var predeclaredIdents = map[string]bool{
	"append": true, "bool": true, "byte": true, "cap": true, "clear": true,
	"close": true, "complex": true, "complex64": true, "complex128": true,
	"copy": true, "delete": true, "error": true, "false": true, "float32": true,
	"float64": true, "imag": true, "int": true, "int8": true, "int16": true,
	"int32": true, "int64": true, "iota": true, "len": true, "make": true,
	"max": true, "min": true, "new": true, "nil": true, "panic": true,
	"print": true, "println": true, "real": true, "recover": true, "rune": true,
	"string": true, "true": true, "uint": true, "uint8": true, "uint16": true,
	"uint32": true, "uint64": true, "uintptr": true, "any": true,
}

func (c *builtinShadow) Visit(n ast.Node) {
	switch n := n.(type) {
	case *ast.AssignStmt:
		for _, e := range n.Lhs {
			id, ok := e.(*ast.Ident)
			if !ok {
				continue
			}
			if predeclaredIdents[id.Name] {
				c.ctx.Warn(id, "shadowing of predeclared identifier: %s", id.Name)
			}
		}
	case *ast.ValueSpec:
		for _, id := range n.Names {
			if predeclaredIdents[id.Name] {
				c.ctx.Warn(id, "shadowing of predeclared identifier: %s", id.Name)
			}
		}
	}
}

// builtinShadowDecl detects top-level declarations that shadow the predeclared
// identifiers.
type builtinShadowDecl struct {
	checkerBase
}

func newBuiltinShadowDecl(c *Context) checker { return &builtinShadowDecl{checkerBase{c}} }

func (c *builtinShadowDecl) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			var names []*ast.Ident
			switch spec := spec.(type) {
			case *ast.TypeSpec:
				names = []*ast.Ident{spec.Name}
			case *ast.ValueSpec:
				names = spec.Names
			case *ast.ImportSpec:
				if spec.Name != nil {
					names = []*ast.Ident{spec.Name}
				}
			}
			for _, id := range names {
				if id == nil {
					continue
				}
				if predeclaredIdents[id.Name] {
					c.ctx.Warn(id, "shadowing of predeclared identifier: %s", id.Name)
				}
			}
		}
	}
}

// importShadow detects shadowing of the imported packages.
type importShadow struct {
	checkerBase
}

func newImportShadow(c *Context) checker { return &importShadow{checkerBase{c}} }

func (c *importShadow) Visit(n ast.Node) {
	switch n := n.(type) {
	case *ast.AssignStmt:
		for _, e := range n.Lhs {
			id, ok := e.(*ast.Ident)
			if !ok {
				continue
			}
			if name := c.ctx.importedPkgName(id.Name); name != "" {
				c.ctx.Warn(id, "shadow of imported package '%s'", name)
			}
		}
	case *ast.ValueSpec:
		for _, id := range n.Names {
			if name := c.ctx.importedPkgName(id.Name); name != "" {
				c.ctx.Warn(id, "shadow of imported package '%s'", name)
			}
		}
	case *ast.FuncDecl:
		if n.Recv != nil {
			return
		}
		if name := c.ctx.importedPkgName(n.Name.Name); name != "" {
			c.ctx.Warn(n.Name, "shadow of imported package '%s'", name)
		}
	}
}

// hugeParam detects functions with heavy parameters.
type hugeParam struct {
	checkerBase
}

func newHugeParam(c *Context) checker { return &hugeParam{checkerBase{c}} }

func (c *hugeParam) Visit(n ast.Node) {
	var fl *ast.FieldList
	switch n := n.(type) {
	case *ast.FuncDecl:
		fl = n.Type.Params
	case *ast.FuncLit:
		fl = n.Type.Params
	}
	if fl == nil {
		return
	}
	threshold := int64(c.ctx.ParamInt("sizeThreshold", 80))
	for _, field := range fl.List {
		t := c.ctx.TypeOf(field.Type)
		if t == nil {
			continue
		}
		size := c.ctx.Sizes.Sizeof(t)
		if size < threshold {
			continue
		}
		for _, id := range field.Names {
			c.ctx.Warn(id, "%s is heavy (%d bytes); consider passing it by pointer", id.Name, size)
		}
	}
}

// rangeValCopy detects loops that copy big objects during each iteration.
type rangeValCopy struct {
	checkerBase
	skipTestFuncs bool
}

func newRangeValCopy(c *Context) checker {
	return &rangeValCopy{checkerBase: checkerBase{c}, skipTestFuncs: c.ParamBool("skipTestFuncs", true)}
}

func (c *rangeValCopy) Visit(n ast.Node) {
	rs, ok := n.(*ast.RangeStmt)
	if !ok || rs.Value == nil {
		return
	}
	if c.skipTestFuncs && c.ctx.inTestFunc() {
		return
	}
	t := c.ctx.TypeOf(rs.Value)
	if t == nil {
		return
	}
	size := c.ctx.Sizes.Sizeof(t)
	if size < int64(c.ctx.ParamInt("sizeThreshold", 128)) {
		return
	}
	c.ctx.Warn(rs, "each iteration copies %d bytes (consider pointers or indexing)", size)
}

// rangeExprCopy detects range expressions that copy big arrays.
type rangeExprCopy struct {
	checkerBase
	skipTestFuncs bool
}

func newRangeExprCopy(c *Context) checker {
	return &rangeExprCopy{checkerBase: checkerBase{c}, skipTestFuncs: c.ParamBool("skipTestFuncs", true)}
}

func (c *rangeExprCopy) Visit(n ast.Node) {
	rs, ok := n.(*ast.RangeStmt)
	if !ok || rs.Key != nil || rs.Value != nil {
		return
	}
	if c.skipTestFuncs && c.ctx.inTestFunc() {
		return
	}
	t := c.ctx.TypeOf(rs.X)
	if t == nil {
		return
	}
	arr, ok := t.Underlying().(*types.Array)
	if !ok {
		return
	}
	size := c.ctx.Sizes.Sizeof(arr)
	if size < int64(c.ctx.ParamInt("sizeThreshold", 512)) {
		return
	}
	x := c.ctx.render(rs.X)
	c.ctx.Warn(rs, "copy of %s (%d bytes) can be avoided with &%s", x, size, x)
}

// typeDefFirst detects type definitions that appear after their methods.
type typeDefFirst struct {
	checkerBase
}

func newTypeDefFirst(c *Context) checker { return &typeDefFirst{checkerBase{c}} }

func (c *typeDefFirst) EnterFile(f *ast.File) {
	typeDefs := map[string]int{}
	var order []string
	for i, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			ts, ok := spec.(*ast.TypeSpec)
			if !ok {
				continue
			}
			if _, ok := typeDefs[ts.Name.Name]; !ok {
				typeDefs[ts.Name.Name] = i
				order = append(order, ts.Name.Name)
			}
		}
	}
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) != 1 {
			continue
		}
		name := c.ctx.recvTypeName(fd.Recv.List[0].Type)
		if name == "" {
			continue
		}
		idx, ok := typeDefs[name]
		if !ok {
			continue
		}
		if declIdx := c.ctx.declIndex(f, decl); declIdx > idx {
			c.ctx.Warn(fd, "definition of type '%s' should appear before its methods", name)
		}
	}
}

func (c *typeDefFirst) recvTypeName(e ast.Expr) string {
	switch t := e.(type) {
	case *ast.StarExpr:
		return c.recvTypeName(t.X)
	case *ast.Ident:
		return t.Name
	case *ast.IndexExpr:
		return c.recvTypeName(t.X)
	case *ast.IndexListExpr:
		return c.recvTypeName(t.X)
	}
	return ""
}

// initClause detects if statements that can be simplified.
type initClause struct {
	checkerBase
}

func newInitClause(c *Context) checker { return &initClause{checkerBase{c}} }

func (c *initClause) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok || ife.Init == nil || ife.Else != nil {
		return
	}
	// The init clause should be a simple statement that does not depend on
	// the condition.
	assign, ok := ife.Init.(*ast.AssignStmt)
	if !ok {
		return
	}
	if len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	switch assign.Tok {
	case token.ASSIGN, token.DEFINE:
	default:
		return
	}
	// The condition should not reference the assigned variable.
	condVars := c.ctx.idents(ife.Cond)
	for _, e := range assign.Lhs {
		if id, ok := e.(*ast.Ident); ok && condVars[id.Name] {
			return
		}
	}
	c.ctx.Warn(ife.Init, "consider to move `%s` before if", c.ctx.render(ife.Init))
}

