func newPreferFilepathJoin(c *Context) checker { return &preferFilepathJoin{checkerBase{c}} }

// preferFprint detects io.WriteString calls that can be replaced.
type preferFprint struct {
	checkerBase
}

func newPreferFprint(c *Context) checker { return &preferFprint{checkerBase{c}} }

// preferStringWriter detects buf.Write([]byte(s)) calls.
type preferStringWriter struct {
	checkerBase
}

func newPreferStringWriter(c *Context) checker { return &preferStringWriter{checkerBase{c}} }

func (c *preferStringWriter) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || identName(sel.Sel) != "Write" {
		return
	}
	conv, ok := unparen(call.Args[0]).(*ast.CallExpr)
	if !ok || len(conv.Args) != 1 {
		return
	}
	if identName(conv.Fun) != "[]byte" && !isByteSliceConv(conv) {
		return
	}
	arg := conv.Args[0]
	t := c.ctx.TypeOf(arg)
	if t == nil || t.Underlying() != types.Typ[types.String] {
		return
	}
	recv := c.ctx.render(sel.X)
	argTxt := c.ctx.render(arg)
	newExpr := recv + ".WriteString(" + argTxt + ")"
	oldExpr := recv + ".Write([]byte(" + argTxt + "))"
	c.ctx.WarnSuggest(call, newExpr, "%s should be preferred to the %s",
		shortenString(newExpr, 96), shortenString(oldExpr, 96))
}

// isByteSliceConv reports whether the call is a `[]byte(...)` conversion.
func isByteSliceConv(call *ast.CallExpr) bool {
	switch fun := call.Fun.(type) {
	case *ast.ArrayType:
		return fun.Len == nil
	}
	return false
}

// preferWriteByte detects w.Write([]byte("x")) calls that can use WriteByte.
type preferWriteByte struct {
	checkerBase
}

func newPreferWriteByte(c *Context) checker { return &preferWriteByte{checkerBase{c}} }

func (c *preferWriteByte) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || identName(sel.Sel) != "Write" {
		return
	}
	conv, ok := unparen(call.Args[0]).(*ast.CallExpr)
	if !ok || len(conv.Args) != 1 || !isByteSliceConv(conv) {
		return
	}
	lit, ok := unparen(conv.Args[0]).(*ast.BasicLit)
	if !ok || lit.Kind != token.STRING {
		return
	}
	v, err := strconv.Unquote(lit.Value)
	if err != nil || utf8Len(v) != 1 {
		return
	}
	recv := c.ctx.render(sel.X)
	r := []rune(v)[0]
	c.ctx.Warn(call, "consider writing single byte rune '%c' with %s.WriteByte('%c')", r, recv, r)
}

// ptrToRefParam detects pointer-to-reference parameters.
type ptrToRefParam struct {
	checkerBase
}

func newPtrToRefParam(c *Context) checker { return &ptrToRefParam{checkerBase{c}} }

func (c *ptrToRefParam) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Type.Params == nil {
			continue
		}
		for _, field := range fd.Type.Params.List {
			t := c.ctx.TypeOf(field.Type)
			if t == nil {
				continue
			}
			ptr, ok := t.(*types.Pointer)
			if !ok {
				continue
			}
			switch ptr.Elem().Underlying().(type) {
			case *types.Map, *types.Chan, *types.Interface, *types.Signature:
			default:
				continue
			}
			for _, id := range field.Names {
				c.ctx.Warn(id, "consider `%s' to be of non-pointer type", id.Name)
			}
		}
	}
}

