func newHttpNoBody(c *Context) checker { return &httpNoBody{checkerBase{c}} }

func (c *httpNoBody) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || len(call.Args) != 3 {
		return
	}
	name := c.ctx.callName(call)
	if name != "http.NewRequest" && name != "http.NewRequestWithContext" {
		return
	}
	if id, ok := unparen(call.Args[2]).(*ast.Ident); !ok || id.Name != "nil" {
		return
	}
