// dupImport detects duplicated imports.
type dupImport struct {
	checkerBase
}

func newDupImport(c *Context) checker { return &dupImport{checkerBase{c}} }

func (c *dupImport) EnterFile(f *ast.File) {
	seen := map[string][]*ast.ImportSpec{}
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			imp, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}
			seen[imp.Path.Value] = append(seen[imp.Path.Value], imp)
		}
	}
	for _, specs := range seen {
		if len(specs) < 2 {
			continue
		}
		for i := 0; i < len(specs)-1; i++ {
			a, b := specs[i], specs[i+1]
			c.ctx.Warn(b, "package is imported %d times under different aliases on lines %d and %d",
				len(specs), c.ctx.line(a), c.ctx.line(b))
		}
	}
}

// stringConcatSimplify detects string concatenations that can be simplified.
type stringConcatSimplify struct {
	checkerBase
}

func newStringConcatSimplify(c *Context) checker { return &stringConcatSimplify{checkerBase{c}} }

func (c *stringConcatSimplify) Visit(n ast.Node) {
	bin, ok := n.(*ast.BinaryExpr)
	if !ok || bin.Op != token.ADD {
		return
	}
	// "a" + string(os.PathSeparator) + "b" -> filepath.Join-like suggestion.
	var parts []string
	e := ast.Expr(bin)
	for {
		b, ok := unparen(e).(*ast.BinaryExpr)
		if !ok || b.Op != token.ADD {
			break
		}
		parts = append([]string{c.part(b.Y)}, parts...)
		e = b.X
	}
	parts = append([]string{c.part(e)}, parts...)
	_ = parts
}

func (c *stringConcatSimplify) part(e ast.Expr) string {
	call, ok := unparen(e).(*ast.CallExpr)
	if !ok || len(call.Args) != 1 {
		return c.ctx.render(e)
	}
	if conv, ok := call.Fun.(*ast.Ident); ok && conv.Name == "string" {
		_ = conv
	}
	return c.ctx.render(e)
}

