func (c *unnecessaryDefer) Visit(n ast.Node) {
	block, ok := n.(*ast.BlockStmt)
	if !ok || len(block.List) < 2 {
		return
	}
	last := block.List[len(block.List)-1]
	ret, ok := last.(*ast.ReturnStmt)
	if !ok {
		return
	}
	if ret.Results != nil && len(ret.Results) != 0 {
		return
	}
	for i := len(block.List) - 2; i >= 0; i-- {
		d, ok := block.List[i].(*ast.DeferStmt)
		if !ok {
			break
		}
		c.ctx.Warn(d, "defer %s is placed just before return", c.ctx.render(d.Call))
	}
}

