	max := c.ctx.ParamInt("maxResults", 5)
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Type.Results == nil {
			continue
		}
		n := 0
		for _, field := range fd.Type.Results.List {
			if len(field.Names) == 0 {
				n++
			} else {
				n += len(field.Names)
			}
		}
		if n <= max {
			continue
		}
		c.ctx.Warn(fd, "function has more than %d results, consider to simplify the function", max)
