func newPtrToRefParam(c *Context) checker { return &ptrToRefParam{checkerBase{c}} }

func (c *ptrToRefParam) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
