// typeUnparen detects redundant parentheses in type expressions.
type typeUnparen struct {
	checkerBase
}

func newTypeUnparen(c *Context) checker { return &typeUnparen{checkerBase{c}} }

func (c *typeUnparen) Visit(n ast.Node) {
	switch n := n.(type) {
	case *ast.ParenExpr:
		// (map[string][]string)(x) -> map[string][]string(x)
		switch n.X.(type) {
		case *ast.MapType, *ast.ChanType, *ast.ArrayType, *ast.FuncType:
		default:
			return
		}
		c.ctx.WarnSuggest(n, c.ctx.render(n.X), "could simplify (%s) to %s", c.ctx.render(n.X), c.ctx.render(n.X))
	case *ast.TypeAssertExpr:
		if n.Type == nil {
			return
		}
		paren, ok := n.Type.(*ast.ParenExpr)
		if !ok {
			return
		}
		c.ctx.WarnSuggest(n.Type, c.ctx.render(paren.X), "could simplify (%s) to %s", c.ctx.render(paren.X), c.ctx.render(paren.X))
	}
}

