func newSloppyReassign(c *Context) checker { return &sloppyReassign{checkerBase{c}} }

func (c *sloppyReassign) Visit(n ast.Node) {
	assign, ok := n.(*ast.AssignStmt)
	if !ok || assign.Tok != token.ASSIGN || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	id, ok := assign.Lhs[0].(*ast.Ident)
	if !ok {
		return
	}
	obj := c.ctx.ObjectOf(id)
	if obj == nil {
		return
	}
	// The variable should be declared with `:=` in the same block.
	if !c.ctx.definedWithDefine(obj) {
		return
	}
	c.ctx.WarnSuggest(assign, id.Name+" := "+c.ctx.render(assign.Rhs[0]),
		"re-assignment to `%s` can be replaced with `%s := %s`",
		id.Name, id.Name, c.ctx.render(assign.Rhs[0]))
