// valSwap detects manual swaps.
type valSwapB struct {
	checkerBase
}

func newValSwapB(c *Context) checker { return &valSwapB{checkerBase{c}} }

func (c *valSwapB) Visit(n ast.Node) {
	block, ok := n.(*ast.BlockStmt)
	if !ok || len(block.List) < 3 {
		return
	}
	for i := 0; i+2 < len(block.List); i++ {
		a1, ok := block.List[i].(*ast.AssignStmt)
		if !ok || len(a1.Lhs) != 1 || len(a1.Rhs) != 1 {
			continue
		}
		a2, ok := block.List[i+1].(*ast.AssignStmt)
		if !ok || len(a2.Lhs) != 1 || len(a2.Rhs) != 1 {
			continue
		}
		a3, ok := block.List[i+2].(*ast.AssignStmt)
		if !ok || len(a3.Lhs) != 1 || len(a3.Rhs) != 1 {
			continue
		}
		x, y := c.ctx.render(a1.Lhs[0]), c.ctx.render(a1.Rhs[0])
		if c.ctx.render(a2.Lhs[0]) != y || c.ctx.render(a2.Rhs[0]) != x {
			continue
		}
		if c.ctx.render(a3.Lhs[0]) != x || c.ctx.render(a3.Rhs[0]) != y {
			continue
		}
		c.ctx.Warn(block.List[i], "can re-write with swap %s, %s", x, y)
	}
}

