func (c *unnecessaryDefer) Visit(n ast.Node) {
	block, ok := n.(*ast.BlockStmt)
	if !ok || len(block.List) < 2 {
		return
	}
	last := block.List[len(block.List)-1]
	ret, ok := last.(*ast.ReturnStmt)
	if !ok {
		return
