package main

import (
	"go/ast"
)

// checkFile runs the checker over the given file.
func checkFile(ctx *Context, ch checker, f *ast.File) {
	ch.EnterFile(f)
	walkAST(ctx, ch, f)
}

// walkAST traverses the AST subtree in the depth-first order, calling the
// checker Visit method for every node. Function definitions are entered and
// left with the EnterFunc/LeaveFunc calls.
func walkAST(ctx *Context, ch checker, root ast.Node) {
	var stack []ast.Node
	ast.Inspect(root, func(n ast.Node) bool {
		if n == nil {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if isFuncNode(top) {
				ch.LeaveFunc()
			}
			switch top.(type) {
			case *ast.FuncDecl, *ast.FuncLit:
				ctx.curFuncIsTest = false
				ctx.curDecl = nil
			}
			return false
		}
		fn := isFuncNode(n)
		switch n := n.(type) {
		case *ast.FuncDecl:
			ctx.curDecl = n
			ctx.curFuncIsTest = strings_HasPrefix(n.Name.Name, "Test") ||
				strings_HasPrefix(n.Name.Name, "Benchmark") ||
				strings_HasPrefix(n.Name.Name, "Example")
		case *ast.FuncLit:
			ctx.curDecl = n
		case *ast.ForStmt, *ast.RangeStmt:
			ctx.curInLoop = true
		}
		ch.Visit(n)
		stack = append(stack, n)
		if fn {
			return ch.EnterFunc(n)
		}
		return true
	})
	ctx.curInLoop = false
}

func isFuncNode(n ast.Node) bool {
	switch n.(type) {
	case *ast.FuncDecl, *ast.FuncLit:
		return true
	}
	return false
}

// strings_HasPrefix is a helper to avoid the extra import.
func strings_HasPrefix(s, prefix string) bool {
	return len(s) >= len(prefix) && s[:len(prefix)] == prefix
}
EOF
gofmt -w walker.go && go build -o /tmp/gc1 . 2>&1|head -5; for d in /tmp/k1 /tmp/k5 /tmp/k7 /tmp/k8; do /tmp/difftest.sh $d check -enableAll . 2>&1|head -8; done"}

