// hugeParam detects functions with heavy parameters.
type hugeParam struct {
	checkerBase
}

func newHugeParam(c *Context) checker { return &hugeParam{checkerBase{c}} }

func (c *hugeParam) Visit(n ast.Node) {
	var fl *ast.FieldList
	switch n := n.(type) {
	case *ast.FuncDecl:
		fl = n.Type.Params
	case *ast.FuncLit:
		fl = n.Type.Params
	}
	if fl == nil {
		return
	}
	threshold := int64(c.ctx.ParamInt("sizeThreshold", 80))
	for _, field := range fl.List {
		t := c.ctx.TypeOf(field.Type)
		if t == nil {
			continue
		}
		size := c.ctx.Sizes.Sizeof(t)
		if size < threshold {
			continue
		}
		for _, id := range field.Names {
			c.ctx.Warn(id, "%s is heavy (%d bytes); consider passing it by pointer", id.Name, size)
		}
	}
}

// rangeValCopy detects loops that copy big objects during each iteration.
type rangeValCopy struct {
	checkerBase
}

func newRangeValCopy(c *Context) checker { return &rangeValCopy{checkerBase{c}} }

func (c *rangeValCopy) Visit(n ast.Node) {
	rs, ok := n.(*ast.RangeStmt)
	if !ok || rs.Value == nil {
		return
	}
	if c.ctx.ParamBool("skipTestFuncs", true) && c.ctx.curFuncIsTest {
		return
	}
	t := c.ctx.TypeOf(rs.Value)
	if t == nil {
		t = c.ctx.rangeValue(rs)
	}
	if t == nil {
		return
	}
	size := c.ctx.Sizes.Sizeof(t)
	if size < int64(c.ctx.ParamInt("sizeThreshold", 128)) {
		return
	}
	c.ctx.Warn(rs, "each iteration copies %d bytes (consider pointers or indexing)", size)
}

// rangeExprCopy detects range expressions that copy big arrays.
type rangeExprCopy struct {
	checkerBase
}

func newRangeExprCopy(c *Context) checker { return &rangeExprCopy{checkerBase{c}} }

func (c *rangeExprCopy) Visit(n ast.Node) {
	rs, ok := n.(*ast.RangeStmt)
	if !ok || rs.Key != nil || rs.Value != nil {
		return
	}
	if c.ctx.ParamBool("skipTestFuncs", true) && c.ctx.curFuncIsTest {
		return
	}
	t := c.ctx.TypeOf(rs.X)
	if t == nil {
		return
	}
	arr, ok := t.Underlying().(*types.Array)
	if !ok {
		return
	}
	size := c.ctx.Sizes.Sizeof(arr)
	if size < int64(c.ctx.ParamInt("sizeThreshold", 512)) {
		return
	}
	x := c.ctx.render(rs.X)
	c.ctx.Warn(rs, "copy of %s (%d bytes) can be avoided with &%s", x, size, x)
}

// typeDefFirst detects type definitions that appear after their methods.
type typeDefFirst struct {
	checkerBase
}

func newTypeDefFirst(c *Context) checker { return &typeDefFirst{checkerBase{c}} }

func (c *typeDefFirst) EnterFile(f *ast.File) {
	if disabledCheck {
		return
	}
	typeDefs := map[string]int{}
	for i, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			if ts, ok := spec.(*ast.TypeSpec); ok {
				if _, ok := typeDefs[ts.Name.Name]; !ok {
					typeDefs[ts.Name.Name] = i
				}
			}
		}
	}
	for _, decl := range f.Decls {
		fd, ok := decl.(*ast.FuncDecl)
		if !ok || fd.Recv == nil || len(fd.Recv.List) != 1 {
			continue
		}
		name := c.ctx.recvTypeName(fd.Recv.List[0].Type)
		idx, ok := typeDefs[name]
		if !ok {
			continue
		}
		if c.ctx.declIndex(f, decl) > idx {
			c.ctx.Warn(fd, "definition of type '%s' should appear before its methods", name)
		}
	}
}

