func newZeroByteRepeat(c *Context) checker { return &zeroByteRepeat{checkerBase{c}} }

func (c *zeroByteRepeat) Visit(n ast.Node) {
	call, ok := n.(*ast.CallExpr)
	if !ok || c.ctx.callName(call) != "bytes.Repeat" || len(call.Args) != 2 {
		return
	}
	lit, ok := unparen(call.Args[0]).(*ast.CompositeLit)
	if !ok || len(lit.Elts) != 1 {
		return
	}
	el, ok := unparen(lit.Elts[0]).(*ast.BasicLit)
	if !ok || el.Value != "0" {
		return
	}
	suggest := "make([]byte, " + c.ctx.render(call.Args[1]) + ")"
	c.ctx.WarnSuggest(call, suggest, "avoid %s; consider using %s instead", c.ctx.render(call), suggest)
}

