// paramTypeCombine combines the parameters of the same type.
type paramTypeCombine struct {
	checkerBase
}

func newParamTypeCombine(c *Context) checker { return &paramTypeCombine{checkerBase{c}} }

func (c *paramTypeCombine) Visit(n ast.Node) {
	switch n := n.(type) {
	case *ast.FuncDecl:
		c.checkFieldList(n.Type.Params, "func", n.Type.Results)
	case *ast.FuncLit:
		c.checkFieldList(n.Type.Params, "func", n.Type.Results)
	}
}

func (c *paramTypeCombine) checkFieldList(fl *ast.FieldList, prefix string, results *ast.FieldList) {
	if fl == nil || len(fl.List) < 2 {
		return
	}
	if c.combine(fl) {
		c.ctx.WarnSuggest(c.ctx.curDecl, c.committed(fl),
			"%s(%s) %scould be replaced with %s(%s) %s",
			prefix, c.renderFields(fl), c.resultsPrefix(results), prefix, c.committed(fl), c.resultsText(results))
	}
}

func (c *paramTypeCombine) combine(fl *ast.FieldList) bool {
	changed := false
	for i := 0; i < len(fl.List); i++ {
		if len(fl.List[i].Names) == 0 {
			continue
		}
		j := i
		for j+1 < len(fl.List) && len(fl.List[j+1].Names) != 0 &&
			c.ctx.exprText(fl.List[j+1].Type) == c.ctx.exprText(fl.List[i].Type) {
			j++
		}
		if j > i {
			changed = true
		}
		i = j
	}
	return changed
}

func (c *paramTypeCombine) committed(fl *ast.FieldList) string {
	var parts []string
	for i := 0; i < len(fl.List); i++ {
		if len(fl.List[i].Names) == 0 {
			parts = append(parts, c.ctx.exprText(fl.List[i].Type))
			continue
		}
		j := i
		names := []string{}
		for j < len(fl.List) && len(fl.List[j].Names) != 0 &&
			c.ctx.exprText(fl.List[j].Type) == c.ctx.exprText(fl.List[i].Type) {
			for _, id := range fl.List[j].Names {
				names = append(names, id.Name)
			}
			j++
		}
		parts = append(parts, strings.Join(names, ", ")+" "+c.ctx.exprText(fl.List[i].Type))
		i = j - 1
	}
	return strings.Join(parts, ", ")
}

func (c *paramTypeCombine) renderFields(fl *ast.FieldList) string {
	var parts []string
	for _, field := range fl.List {
		names := []string{}
		for _, id := range field.Names {
			names = append(names, id.Name)
		}
		if len(names) == 0 {
			parts = append(parts, c.ctx.exprText(field.Type))
			continue
		}
		parts = append(parts, strings.Join(names, ", ")+" "+c.ctx.exprText(field.Type))
	}
	return strings.Join(parts, ", ")
}

func (c *paramTypeCombine) resultsText(fl *ast.FieldList) string {
	if fl == nil || len(fl.List) == 0 {
		return ""
	}
	return c.ctx.exprText(fl)
}

func (c *paramTypeCombine) resultsPrefix(fl *ast.FieldList) string {
	if fl == nil || len(fl.List) == 0 {
		return ""
	}
	return ""
}

// builtinShadow detects shadowing of the predeclared identifiers.
type builtinShadow struct {
	checkerBase
}

func newBuiltinShadow(c *Context) checker { return &builtinShadow{checkerBase{c}} }

var predeclaredIdents = map[string]bool{
	"append": true, "bool": true, "byte": true, "cap": true, "clear": true,
	"close": true, "complex": true, "complex64": true, "complex128": true,
	"copy": true, "delete": true, "error": true, "false": true, "float32": true,
	"float64": true, "imag": true, "int": true, "int8": true, "int16": true,
	"int32": true, "int64": true, "iota": true, "len": true, "make": true,
	"max": true, "min": true, "new": true, "nil": true, "panic": true,
	"print": true, "println": true, "real": true, "recover": true, "rune": true,
	"string": true, "true": true, "uint": true, "uint8": true, "uint16": true,
	"uint32": true, "uint64": true, "uintptr": true, "any": true,
}

func (c *builtinShadow) Visit(n ast.Node) {
	var names []*ast.Ident
	switch n := n.(type) {
	case *ast.AssignStmt:
		if n.Tok != token.DEFINE {
			return
		}
		for _, e := range n.Lhs {
			if id, ok := e.(*ast.Ident); ok {
				names = append(names, id)
			}
		}
	case *ast.ValueSpec:
		names = n.Names
	case *ast.Field:
		names = n.Names
	}
	for _, id := range names {
		if id == nil {
			continue
		}
		if predeclaredIdents[id.Name] {
			c.ctx.Warn(id, "shadowing of predeclared identifier: %s", id.Name)
		}
	}
}

// builtinShadowDecl detects top-level declarations that shadow the predeclared
// identifiers.
type builtinShadowDecl struct {
	checkerBase
}

func newBuiltinShadowDecl(c *Context) checker { return &builtinShadowDecl{checkerBase{c}} }

func (c *builtinShadowDecl) EnterFile(f *ast.File) {
	for _, decl := range f.Decls {
		var names []*ast.Ident
		switch decl := decl.(type) {
		case *ast.GenDecl:
			for _, spec := range decl.Specs {
				switch spec := spec.(type) {
				case *ast.TypeSpec:
					names = append(names, spec.Name)
				case *ast.ValueSpec:
					names = append(names, spec.Names...)
				case *ast.ImportSpec:
					if spec.Name != nil {
						names = append(names, spec.Name)
					}
				}
			}
		case *ast.FuncDecl:
			names = append(names, decl.Name)
		}
		for _, id := range names {
			if id == nil {
				continue
			}
			if predeclaredIdents[id.Name] {
				c.ctx.Warn(id, "shadowing of predeclared identifier: %s", id.Name)
			}
		}
	}
}

