func newInitClause(c *Context) checker { return &initClause{checkerBase{c}} }

func (c *initClause) Visit(n ast.Node) {
	ife, ok := n.(*ast.IfStmt)
	if !ok || ife.Init == nil || ife.Else != nil {
		return
	}
	assign, ok := ife.Init.(*ast.AssignStmt)
	if !ok || len(assign.Lhs) != 1 || len(assign.Rhs) != 1 {
		return
	}
	switch assign.Tok {
	case token.ASSIGN, token.DEFINE:
	default:
		return
	}
	condVars := c.ctx.idents(ife.Cond)
	for _, e := range assign.Lhs {
		if id, ok := e.(*ast.Ident); ok && condVars[id.Name] {
			return
		}
	}
	c.ctx.Warn(ife.Init, "consider to move `%s` before if", c.ctx.render(ife.Init))
}

