// dupImport detects duplicated imports.
type dupImport struct {
	checkerBase
}

func newDupImport(c *Context) checker { return &dupImport{checkerBase{c}} }

func (c *dupImport) EnterFile(f *ast.File) {
	seen := map[string][]*ast.ImportSpec{}
	for _, decl := range f.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok {
			continue
		}
		for _, spec := range gd.Specs {
			if imp, ok := spec.(*ast.ImportSpec); ok {
				seen[imp.Path.Value] = append(seen[imp.Path.Value], imp)
			}
		}
	}
	for _, specs := range seen {
		if len(specs) < 2 {
			continue
		}
		for i := 0; i < len(specs)-1; i++ {
			a, b := specs[i], specs[i+1]
			c.ctx.Warn(b, "package is imported %d times under different aliases on lines %d and %d",
				len(specs), c.ctx.line(a), c.ctx.line(b))
		}
	}
}

