	pkg.labelRedundant = map[ast.Node]bool{}

	// Mark the nodes that are located inside a loop but not inside a nested
	// function literal.
	var markLoops func(n ast.Node, inLoop bool)
	markLoops = func(n ast.Node, inLoop bool) {
		ast.Inspect(n, func(n ast.Node) bool {
			if n == nil {
				return false
			}
			if _, ok := n.(*ast.FuncLit); ok {
				markLoops(n, false)
				return false
			}
			if inLoop {
				pkg.loopNodes[n] = true
			}
			switch n := n.(type) {
			case *ast.ForStmt:
				if n.Body != nil {
					markLoops(n.Body, true)
					return false
				}
			case *ast.RangeStmt:
				if n.Body != nil {
					markLoops(n.Body, true)
					return false
				}
			}
			return true
		})
	}

	for _, f := range pkg.Syntax {
		if pkg.importedNames == nil {
			pkg.importedNames = map[string]bool{}
		}
		for _, imp := range f.Imports {
			name := ""
			if imp.Name != nil {
				name = imp.Name.Name
			} else {
				path, err := strconv.Unquote(imp.Path.Value)
				if err != nil {
					continue
				}
				name = path[strings.LastIndex(path, "/")+1:]
			}
			pkg.importedNames[name] = true
		}
		markLoops(f, false)
		// Collect the statement blocks and the label information.
		var stack []ast.Node
		var block *ast.BlockStmt
		ast.Inspect(f, func(n ast.Node) bool {
			if n == nil {
				if len(stack) != 0 {
					stack = stack[:len(stack)-1]
					if len(stack) != 0 {
						block, _ = stack[len(stack)-1].(*ast.BlockStmt)
					}
				}
				return false
			}
			stack = append(stack, n)
			switch n := n.(type) {
			case *ast.BlockStmt:
				for _, s := range n.List {
					pkg.blockOf[s] = n
				}
				block = n
			case *ast.IfStmt:
				if b, ok := n.Else.(*ast.BlockStmt); ok && len(b.List) == 1 {
					if _, ok := b.List[0].(*ast.IfStmt); ok {
						pkg.elseIfNodes[b.List[0]] = true
					}
				}
				if _, ok := n.Else.(*ast.IfStmt); ok {
					pkg.elseIfNodes[n.Else] = true
				}
			case *ast.BranchStmt:
				if n.Label != nil {
					pkg.labelUsed[n.Label.Name] = true
				}
			case *ast.LabeledStmt:
				if _, ok := pkg.labelDecl[n.Label.Name]; !ok {
					pkg.labelDecl[n.Label.Name] = n
				}
			}
			return true
		})
		// A label is redundant when it is only used by the branches that are
		// located directly inside the labeled statement.
		for name, lbl := range pkg.labelDecl {
			usedOutside := false
			ast.Inspect(lbl.Stmt, func(n ast.Node) bool {
				br, ok := n.(*ast.BranchStmt)
				if !ok || br.Label == nil || br.Label.Name != name {
					return true
				}
				if !nearestIsLabeled(pkg, br, lbl) {
					usedOutside = true
				}
				return true
			})
			if !usedOutside {
				pkg.labelRedundant[lbl] = true
			}
		}
		// Collect the comments that are located inside function bodies.
		for _, decl := range f.Decls {
			fd, ok := decl.(*ast.FuncDecl)
			if !ok || fd.Body == nil {
				continue
			}
			pkg.funcBodyRanges = append(pkg.funcBodyRanges, [2]token.Pos{fd.Body.Pos(), fd.Body.End()})
			for _, cg := range f.Comments {
				if cg.Pos() > fd.Body.Pos() && cg.End() < fd.Body.End() {
					pkg.funcComments = append(pkg.funcComments, cg)
				}
			}
		}
	}
}
